const n=[{lessonId:1,lessonKey:"Bài 1",lessonTitleZh:"AI小语，你好！",lessonTitleFull:"Bài 1: AI小语，你好！ (Chào hỏi trong tiếng Trung)",grammarPoints:[{id:"hsk1_b1_g1",num:1,title:"Cách chào hỏi trong tiếng Trung",explanation:'Trong tiếng Trung, câu chào hỏi cơ bản nhất được tạo thành bằng cách ghép đối tượng được chào với tính từ "好" (hǎo). Khi chào người lớn tuổi, cấp trên hoặc người cần bày tỏ sự tôn kính đặc biệt, ta dùng đại từ "您" (nín) thay cho "你" (nǐ).',formula:"[Đối tượng được chào] + 好 (hǎo)",note:"Khi hai thanh 3 đi liền nhau (như 你 nǐ + 好 hǎo), thanh 3 thứ nhất sẽ biến điệu đọc thành thanh 2: /ní hǎo/.",examples:[{rawZh:"你好！ (Chào bạn!)",zh:"你好！",pinyin:"Nǐ hǎo!",vi:"Chào bạn! / Chào cậu!"},{rawZh:"您好！ (Chào ngài/ông/bà - kính trọng)",zh:"您好！",pinyin:"Nín hǎo!",vi:"Chào ngài / Chào ông / Chào bà (thể hiện sự tôn kính)."},{rawZh:"大家好！ (Chào mọi người!)",zh:"大家好！",pinyin:"Dàjiā hǎo!",vi:"Chào tất cả mọi người!"},{rawZh:"你们好！ (Chào các bạn!)",zh:"你们好！",pinyin:"Nǐmen hǎo!",vi:"Chào các bạn! / Chào mọi người!"},{rawZh:"老师好！ (Chào thầy/cô!)",zh:"老师好！",pinyin:"Lǎoshī hǎo!",vi:"Em chào thầy / Em chào cô giáo ạ!"}],tables:[{title:"Bảng tổng hợp các câu chào hỏi thông dụng (HSK 1)",headers:["Chữ Hán","Phiên âm (Pinyin)","Ý nghĩa tiếng Việt","Đối tượng & Hoàn cảnh áp dụng"],rows:[["你好","nǐ hǎo","Chào bạn / Chào cậu","Bạn bè, người ngang hàng hoặc nhỏ tuổi"],["您好","nín hǎo","Chào ngài / ông / bà","Người lớn tuổi, thầy cô, đối tác, khách hàng"],["大家好","dàjiā hǎo","Chào mọi người","Chào một nhóm đông người, hội trường"],["你们好","nǐmen hǎo","Chào các bạn","Chào từ 2 người trở lên"],["老师好","lǎoshī hǎo","Chào thầy / cô","Học sinh chào giáo viên"]]}],exercises:[{type:"Chọn đáp án đúng",prompt:"Khi gặp thầy giáo vào buổi sáng, bạn nên nói câu nào lịch sự nhất?",options:["A. 你好！","B. 老师好！ / 老师您好！","C. 大家好！"],answer:"B. 老师好！ / 老师您好！"}]}]},{lessonId:2,lessonKey:"Bài 2",lessonTitleZh:"我叫李文",lessonTitleFull:"Bài 2: 我叫李文 (Cấu trúc câu cơ bản & Trạng ngữ)",grammarPoints:[{id:"hsk1_b2_g1",num:1,title:"Câu trần thuật cơ bản: Chủ ngữ + Động từ + Tân ngữ (S + V + O)",explanation:"Đây là cấu trúc câu đơn giản và nền tảng nhất trong ngữ pháp tiếng Trung, hoàn toàn tương tự trật tự ngữ pháp trong tiếng Việt.",formula:"Chủ ngữ (S) + Động từ (V) + Tân ngữ (O)",note:'Động từ "叫" (jiào) vừa có nghĩa là "kêu, gọi", vừa có nghĩa là "tên là" khi theo sau là tên riêng.',examples:[{rawZh:"我爱你。(Wǒ ài nǐ.)",zh:"我爱你。",pinyin:"Wǒ ài nǐ.",vi:"Tôi yêu bạn / Anh yêu em."},{rawZh:"他喝茶。(Tā hē chá.)",zh:"他喝茶。",pinyin:"Tā hē chá.",vi:"Anh ấy uống trà."},{rawZh:"我叫李文。(Wǒ jiào Lǐ Wén.)",zh:"我叫李文。",pinyin:"Wǒ jiào Lǐ Wén.",vi:"Tôi tên là Lý Văn."}],tables:null,exercises:null},{id:"hsk1_b2_g2",num:2,title:"Trạng ngữ chỉ Thời gian và Địa điểm",explanation:"Quy tắc vàng trong tiếng Trung: Trạng ngữ chỉ thời gian và trạng ngữ chỉ địa điểm LUÔN LUÔN đứng TRƯỚC động từ vị ngữ, KHÔNG BAO GIỜ được đặt ở cuối câu như tiếng Việt hay tiếng Anh.",formula:`Thời gian + Chủ ngữ + (在 + Địa điểm) + Động từ + Tân ngữ
(hoặc: Chủ ngữ + Thời gian + (在 + Địa điểm) + Động từ + Tân ngữ)`,note:"Thời gian có thể linh hoạt đứng trước hoặc ngay sau Chủ ngữ, nhưng phải luôn đứng trước Động từ.",examples:[{rawZh:"我昨天在学校学习。(Wǒ zuótiān zài xuéxiào xuéxí.)",zh:"我昨天在学校学习。",pinyin:"Wǒ zuótiān zài xuéxiào xuéxí.",vi:"Hôm qua tôi học ở trường."},{rawZh:"老师今天在家里休息。(Lǎoshī jīntiān zài jiālǐ xiūxi.)",zh:"老师今天在家里休息。",pinyin:"Lǎoshī jīntiān zài jiālǐ xiūxi.",vi:"Hôm nay thầy giáo nghỉ ngơi ở nhà."},{rawZh:"姐姐明天在北京工作。(Jiějie míngtiān zài Běijīng gōngzuò.)",zh:"姐姐明天在北京工作。",pinyin:"Jiějie míngtiān zài Běijīng gōngzuò.",vi:"Chị gái ngày mai làm việc ở Bắc Kinh."}],tables:null,exercises:[{type:"Sắp xếp câu",prompt:"Sắp xếp: 学习 / 在学校 / 我 / 今天",answer:"我今天在学校学习。 / 今天我在学校学习。"}]},{id:"hsk1_b2_g3",num:3,title:"Vị trí của phó từ trong câu (不, 很, 也...)",explanation:"Các phó từ phủ định (不 bù), phó từ chỉ mức độ (很 hěn), hoặc phó từ liên kết (也 yě) luôn đứng TRƯỚC Động từ hoặc Tính từ mà chúng bổ nghĩa.",formula:"Chủ ngữ + Phó từ (不 / 很 / 也) + Động từ / Tính từ",note:'Khi có cả "也" và "不", "也" luôn đứng trước "不" (Ví dụ: 我也不去 - Tôi cũng không đi).',examples:[{rawZh:"他不喜⽵。(Tā bù xǐhuan.)",zh:"他不喜⽵。",pinyin:"Tā bù xǐhuan.",vi:"Anh ấy không thích."},{rawZh:"苹果很好。(Píngguǒ hěn hǎo.)",zh:"苹果很好。",pinyin:"Píngguǒ hěn hǎo.",vi:"Táo rất ngon / rất tốt."},{rawZh:"我也认识他。(Wǒ yě rènshi tā.)",zh:"我也认识他。",pinyin:"Wǒ yě rènshi tā.",vi:"Tôi cũng quen biết anh ấy."}],tables:null,exercises:null}]},{lessonId:3,lessonKey:"Bài 3",lessonTitleZh:"我是中国人",lessonTitleFull:"Bài 3: 我是中国人 (Câu chữ 是, Trợ từ 的 & Câu hỏi 吗)",grammarPoints:[{id:"hsk1_b3_g1",num:1,title:"Câu chữ “是” (Khẳng định & Phủ định “不是”)",explanation:'Câu chữ "是" (shì) tương đương với từ "là" trong tiếng Việt, dùng để định danh người, sự vật, quốc tịch, nghề nghiệp. Hình thức phủ định là thêm "不" trước "是" tạo thành "不是" (bú shì).',formula:`Khẳng định: Chủ ngữ + 是 + Tân ngữ
Phủ định: Chủ ngữ + 不是 + Tân ngữ`,note:'Từ "不" (bù - thanh 4) khi đứng trước "是" (shì - thanh 4) sẽ biến điệu đọc thành thanh 2: /bú shì/.',examples:[{rawZh:"我是越南人。(Wǒ shì Yuènán rén.)",zh:"我是越南人。",pinyin:"Wǒ shì Yuènán rén.",vi:"Tôi là người Việt Nam."},{rawZh:"我不是中国人。(Wǒ bú shì Zhōngguó rén.)",zh:"我不是中国人。",pinyin:"Wǒ bú shì Zhōngguó rén.",vi:"Tôi không phải là người Trung Quốc."},{rawZh:"她是我的老师。(Tā shì wǒ de lǎoshī.)",zh:"她是我的老师。",pinyin:"Tā shì wǒ de lǎoshī.",vi:"Cô ấy là giáo viên của tôi."}],tables:null,exercises:null},{id:"hsk1_b3_g2",num:2,title:"Trợ từ kết cấu “的” (Biểu thị mối quan hệ sở hữu)",explanation:'Trợ từ kết cấu "的" (de) đặt giữa Định ngữ (thành phần bổ nghĩa) và Trung tâm ngữ (đối tượng chính) để biểu thị quan hệ sở hữu (nghĩa là "của").',formula:"Định ngữ (Chủ sở hữu) + 的 + Trung tâm ngữ (Vật/Người sở hữu)",note:'Quy tắc lược bỏ "的": Khi định ngữ là đại từ nhân xưng (我, 你, 他...) và trung tâm ngữ là từ chỉ quan hệ thân thuộc (bố, mẹ, thầy cô, bạn bè), ta có thể lược bỏ "的" (Ví dụ: 我老师, 你同学, 我学生, 你妈妈).',examples:[{rawZh:"你的名字 (Nǐ de míngzi)",zh:"你的名字",pinyin:"Nǐ de míngzi",vi:"Tên của bạn"},{rawZh:"你的老师 (Nǐ de lǎoshī)",zh:"你的老师",pinyin:"Nǐ de lǎoshī",vi:"Giáo viên của bạn (có thể nói gọn: 你老师)"},{rawZh:"我的同学 (Wǒ de tóngxué)",zh:"我的同学",pinyin:"Wǒ de tóngxué",vi:"Bạn học của tôi (có thể nói gọn: 我同学)"}],tables:null,exercises:null},{id:"hsk1_b3_g3",num:3,title:"Câu hỏi Có/Không sử dụng trợ từ ngữ khí “吗”",explanation:'Trợ từ ngữ khí "吗" (ma) được đặt ở cuối một câu trần thuật để biến câu đó thành câu nghi vấn Yes/No (nghĩa là: "...phải không?", "...không?").',formula:"Câu trần thuật (S + V + O) + 吗?",note:"Khi trả lời, chỉ cần dùng trực tiếp động từ/tính từ (khẳng định) hoặc 不 + động từ/tính từ (phủ định).",examples:[{rawZh:"你是中国人吗？(Nǐ shì Zhōngguó rén ma?)",zh:"你是中国人吗？",pinyin:"Nǐ shì Zhōngguó rén ma?",vi:"Bạn là người Trung Quốc phải không?"},{rawZh:"你忙吗？(Nǐ máng ma?)",zh:"你忙吗？",pinyin:"Nǐ máng ma?",vi:"Bạn có bận không?"},{rawZh:"你想我吗？(Nǐ xiǎng wǒ ma?)",zh:"你想我吗？",pinyin:"Nǐ xiǎng wǒ ma?",vi:"Bạn có nhớ tôi không?"}],tables:null,exercises:null}]},{lessonId:4,lessonKey:"Bài 4",lessonTitleZh:"我有两个孩子",lessonTitleFull:"Bài 4: 我有两个孩子 (Câu chữ 有, Số đếm 0-10.000 & Danh lượng)",grammarPoints:[{id:"hsk1_b4_g1",num:1,title:"Câu chữ “有” (Biểu thị sự sở hữu & Tồn tại)",explanation:'Động từ "有" (yǒu) có nghĩa là "có", dùng để biểu thị sự sở hữu. Hình thức phủ định bắt buộc phải dùng "没有" (méiyǒu), tuyệt đối không được dùng "不有".',formula:`Khẳng định: Chủ ngữ + 有 + Tân ngữ
Phủ định: Chủ ngữ + 没有 + Tân ngữ
Nghi vấn: Chủ ngữ + 有 + Tân ngữ + 吗?`,note:'Trong khẩu ngữ, phủ định "没有" có thể nói tắt thành "没" (Ví dụ: 我没钱 - Tôi không có tiền).',examples:[{rawZh:"我有两个孩子。(Wǒ yǒu liǎng gè háizi.)",zh:"我有两个孩子。",pinyin:"Wǒ yǒu liǎng gè háizi.",vi:"Tôi có hai đứa con."},{rawZh:"我没有姐姐。(Wǒ méiyǒu jiějie.)",zh:"我没有姐姐。",pinyin:"Wǒ méiyǒu jiějie.",vi:"Tôi không có chị gái."},{rawZh:"你有手机吗？(Nǐ yǒu shǒujī ma?)",zh:"你有手机吗？",pinyin:"Nǐ yǒu shǒujī ma?",vi:"Bạn có điện thoại di động không?"}],tables:null,exercises:null},{id:"hsk1_b4_g2",num:2,title:"Cách diễn đạt các con số (0 - 10.000) & Phân biệt 二 và 两",explanation:"Trong tiếng Trung, các con số được diễn đạt theo hệ thập phân với các đơn vị: 十 (10), 百 (100), 千 (1.000), 万 (10.000).",formula:"[Hàng chục vạn] + 万 + [Hàng ngàn] + 千 + [Hàng trăm] + 百 + [Hàng chục] + 十 + [Đơn vị]",note:`Quy tắc phân biệt 二 (èr) và 两 (liǎng):
1. 二 (èr): Dùng cho số đếm (1, 2, 3), số thứ tự (第二), hàng chục (二十), phân số, số điện thoại, ngày tháng năm.
2. 两 (liǎng): Dùng trước LƯỢNG TỪ (两个人, 两本书) và các hàng ngàn, vạn (两千, 两万).
3. Hàng trăm: Cả 二百 và 两百 đều được chấp nhận.`,examples:[{rawZh:"一百 (100)",zh:"一百",pinyin:"yì bǎi",vi:"100 (Một trăm)"},{rawZh:"二百零五 (205)",zh:"二百零五",pinyin:"èrbǎi líng wǔ",vi:"205 (Hai trăm lẻ năm)"},{rawZh:"四百一十 (410)",zh:"四百一十",pinyin:"sìbǎi yīshí",vi:"410 (Bốn trăm mười)"},{rawZh:"三千零八 (3008)",zh:"三千零八",pinyin:"sānqiān líng bā",vi:"3008 (Ba ngàn không trăm lẻ tám)"},{rawZh:"一万 (10000)",zh:"一万",pinyin:"yí wàn",vi:"10.000 (Mười ngàn / Một vạn)"}],tables:[{title:"Bảng cách đọc và viết số từ 0 - 99",headers:["Chữ Hán & Pinyin","Số","Chữ Hán & Pinyin","Số"],rows:[["零 (líng)","0","十 (shí)","10"],["一 (yī)","1","十一 (shíyī)","11"],["二 (èr)","2","二十 (èrshí)","20"],["三 (sān)","3","二十一 (èrshíyī)","21"],["四 (sì)","4","三十 (sānshí)","30"],["五 (wǔ)","5","四十 (sìshí)","40"],["六 (liù)","6","五十 (wǔshí)","50"],["七 (qī)","7","六十 (liùshí)","60"],["八 (bā)","8","七十 (qīshí)","70"],["九 (jiǔ)","9","八十 (bāshí)","80"],["...","...","九十九 (jiǔshíjiǔ)","99"]]},{title:"Bảng phân cấp hàng đơn vị số lớn từ 100 - 10,000",headers:["Hàng Chục Ngàn (万 wàn)","Hàng Ngàn (千 qiān)","Hàng Trăm (百 bǎi)","Hàng Chục (十 shí)","Đơn Vị"],rows:[["10,000: 一万 (yí wàn)","1,000: 一千 (yì qiān)","100: 一百 (yì bǎi)","10: 十 (shí)","1: 一 (yī)"],["20,000: 两万 (liǎng wàn)","3,008: 三千零八","205: 二百零五","410: 四百一十","222: 二百二十二"]]}],exercises:null},{id:"hsk1_b4_g3",num:3,title:"Trợ từ ngữ khí “呢” (1) - Dùng để hỏi ngược lại",explanation:'Trợ từ "呢" (ne) đặt sau danh từ hoặc đại từ để hỏi ngược lại về một chủ đề/tình huống đã được nhắc đến ở câu trước (tương đương "Còn... thì sao?").',formula:"[Đối tượng / Sự vật] + 呢?",note:"Cấu trúc này giúp tránh lặp lại toàn bộ câu hỏi dài phía trước.",examples:[{rawZh:"我是老师，你呢？(Wǒ shì lǎoshī, nǐ ne?)",zh:"我是老师，你呢？",pinyin:"Wǒ shì lǎoshī, nǐ ne?",vi:"Tôi là giáo viên, còn bạn thì sao?"},{rawZh:"我是越南人，你呢？(Wǒ shì Yuènán rén, nǐ ne?)",zh:"我是越南人，你呢？",pinyin:"Wǒ shì Yuènán rén, nǐ ne?",vi:"Tôi là người Việt Nam, còn bạn thì sao?"},{rawZh:"我很好，你呢？(Wǒ hěn hǎo, nǐ ne?)",zh:"我很好，你呢？",pinyin:"Wǒ hěn hǎo, nǐ ne?",vi:"Tôi rất khỏe, còn bạn thì sao?"}],tables:null,exercises:null},{id:"hsk1_b4_g4",num:4,title:"Cấu trúc Danh Lượng: Số từ + Lượng từ + Danh từ",explanation:"Nguyên tắc bắt buộc trong tiếng Trung: Khi chỉ số lượng của sự vật, giữa Số từ và Danh từ BẮT BUỘC phải có Lượng từ, không được bỏ qua lượng từ.",formula:"Số từ + Lượng từ + Danh từ",note:'Mỗi danh từ thường có một lượng từ chuyên dụng đi kèm. Khi chưa rõ lượng từ riêng của một vật, có thể dùng lượng từ thông dụng nhất là "个" (gè).',examples:[{rawZh:"三个人 (sān gè rén)",zh:"三个人",pinyin:"sān gè rén",vi:"Ba người (Lượng từ: 个)"},{rawZh:"一本书 (yì běn shū)",zh:"一本书",pinyin:"yì běn shū",vi:"Một quyển sách (Lượng từ: 本)"},{rawZh:"四个学生 (sì gè xuésheng)",zh:"四个学生",pinyin:"sì gè xuésheng",vi:"Bốn học sinh (Lượng từ: 个)"}],tables:null,exercises:null}]},{lessonId:5,lessonKey:"Bài 5",lessonTitleZh:"今天我休息",lessonTitleFull:"Bài 5: 今天我休息 (Thời gian Ngày Tháng Năm Thứ, Câu vị ngữ danh từ, Động từ năng nguyện 会)",grammarPoints:[{id:"hsk1_b5_g1",num:1,title:"Cách diễn đạt Thời gian (1): Năm - Tháng - Ngày - Thứ",explanation:"Tiếng Trung diễn đạt thời gian theo quy luật tư duy từ LỚN đến BÉ: Năm (年 nián) -> Tháng (月 yuè) -> Ngày (日 rì / 号 hào) -> Thứ (星期 xīngqī). Năm được đọc lần lượt từng chữ số một.",formula:"[Năm] 年 + [Tháng] 月 + [Ngày] 日/号 + [Thứ] 星期",note:'Trong văn viết dùng "日" (rì), trong khẩu ngữ thường ngày hay dùng "号" (hào).',examples:[{rawZh:"2026年8月2日，星期日。(èr líng èr liù nián bā yuè èr rì, xīngqī rì)",zh:"2026年8月2日，星期日。",pinyin:"èr líng èr liù nián bā yuè èr rì, xīngqī rì",vi:"Chủ nhật, ngày 2 tháng 8 năm 2026."},{rawZh:"5月15日，星期二。(wǔ yuè shíwǔ rì, xīngqī èr)",zh:"5月15日，星期二。",pinyin:"wǔ yuè shíwǔ rì, xīngqī èr",vi:"Thứ 3, ngày 15 tháng 5."}],tables:[{title:"Bảng 12 Tháng trong năm (月 yuè)",headers:["Tháng","Chữ Hán & Pinyin","Tháng","Chữ Hán & Pinyin"],rows:[["Tháng 1","一月 (yī yuè)","Tháng 7","七月 (qī yuè)"],["Tháng 2","二月 (èr yuè)","Tháng 8","八月 (bā yuè)"],["Tháng 3","三月 (sān yuè)","Tháng 9","九月 (jiǔ yuè)"],["Tháng 4","四月 (sì yuè)","Tháng 10","十月 (shí yuè)"],["Tháng 5","五月 (wǔ yuè)","Tháng 11","十一月 (shí yī yuè)"],["Tháng 6","六月 (liù yuè)","Tháng 12","十二月 (shí èr yuè)"]]},{title:"Bảng các Thứ trong tuần (星期 xīngqī)",headers:["Thứ","Chữ Hán & Pinyin","Thứ","Chữ Hán & Pinyin"],rows:[["Thứ 2","星期一 (xīngqī yī)","Thứ 6","星期五 (xīngqī wǔ)"],["Thứ 3","星期二 (xīngqī èr)","Thứ 7","星期六 (xīngqī liù)"],["Thứ 4","星期三 (xīngqī sān)","Chủ Nhật","星期日 / 星期天 (xīngqī rì / tiān)"],["Thứ 5","星期四 (xīngqī sì)","",""]]}],exercises:[{type:"Sắp xếp câu",prompt:"Sắp xếp: 是 / 2026年 / 8月 / 今天 / 星期日 / 2日",answer:"今天是2026年8月2日，星期日。"}]},{id:"hsk1_b5_g2",num:2,title:"Câu vị ngữ danh từ (Không dùng động từ “是”)",explanation:'Là loại câu dùng trực tiếp danh từ hoặc cụm danh từ làm vị ngữ để miêu tả ngày tháng, thời gian, tuổi tác, quê quán, giá cả mà KHÔNG cần dùng động từ "是".',formula:"Chủ ngữ + Danh từ / Cụm danh từ",note:'Khi phủ định, bắt buộc phải dùng "不是" (Ví dụ: 今天不是星期日 - Hôm nay không phải là Chủ nhật).',examples:[{rawZh:"今天星期日。(Jīntiān xīngqī rì.)",zh:"今天星期日。",pinyin:"Jīntiān xīngqī rì.",vi:"Hôm nay là Chủ nhật."},{rawZh:"今天八月三号。(Jīntiān bā yuè sān hào.)",zh:"今天八月三号。",pinyin:"Jīntiān bā yuè sān hào.",vi:"Hôm nay là ngày 3 tháng 8."},{rawZh:"我二十岁。(Wǒ èrshí suì.)",zh:"我二十岁。",pinyin:"Wǒ èrshí suì.",vi:"Tôi 20 tuổi."}],tables:null,exercises:null},{id:"hsk1_b5_g3",num:3,title:"Động từ năng nguyện “会” (Kỹ năng do học tập/rèn luyện)",explanation:'Động từ năng nguyện "会" (huì) dùng để biểu thị năng lực, kỹ năng làm được một việc gì đó thông qua quá trình học tập hoặc rèn luyện (biết làm gì).',formula:`Khẳng định: S + 会 + V + O
Phủ định: S + 不会 + V + O
Nghi vấn: S + 会 + V + O + 吗?`,note:'Phủ định của "会" là "不会" (bú huì).',examples:[{rawZh:"我会说中文。(Wǒ huì shuō Zhōngwén.)",zh:"我会说中文。",pinyin:"Wǒ huì shuō Zhōngwén.",vi:"Tôi biết nói tiếng Trung."},{rawZh:"他不会开车。(Tā bú huì kāichē.)",zh:"他不会开车。",pinyin:"Tā bú huì kāichē.",vi:"Anh ấy không biết lái xe."},{rawZh:"我会做饭。(Wǒ huì zuòfàn.)",zh:"我会做饭。",pinyin:"Wǒ huì zuòfàn.",vi:"Tôi biết nấu ăn."}],tables:null,exercises:null}]},{lessonId:6,lessonKey:"Bài 6",lessonTitleZh:"你的手机号是多少?",lessonTitleFull:"Bài 6: 你的手机号是多少? (Động từ năng nguyện 想, Câu liên động & Đại từ 怎么)",grammarPoints:[{id:"hsk1_b6_g1",num:1,title:"Động từ năng nguyện “想” (Biểu thị mong muốn, ý định)",explanation:'Động từ năng nguyện "想" (xiǎng) đứng trước động từ chính để biểu thị mong muốn, dự định hoặc nguyện vọng làm một việc gì đó (nghĩa là "muốn", "dự định").',formula:`Khẳng định: S + 想 + V + O
Phủ định: S + 不想 + V + O
Nghi vấn: S + 想 + V + O + 吗? / S + 想 + V + 什么?`,note:'Ngoài nghĩa "muốn", "想" khi đi trực tiếp với danh từ còn có nghĩa là "nhớ" (Ví dụ: 我想你 - Tôi nhớ bạn) hoặc "nghĩ/suy nghĩ".',examples:[{rawZh:"我想去超市。(Wǒ xiǎng qù chāoshì.)",zh:"我想去超市。",pinyin:"Wǒ xiǎng qù chāoshì.",vi:"Tôi muốn đi siêu thị."},{rawZh:"妈妈不想买电脑。(Māma bù xiǎng mǎi diànnǎo.)",zh:"妈妈不想买电脑。",pinyin:"Māma bù xiǎng mǎi diànnǎo.",vi:"Mẹ không muốn mua máy tính."},{rawZh:"你想吃什么？(Nǐ xiǎng chī shénme?)",zh:"你想吃什么？",pinyin:"Nǐ xiǎng chī shénme?",vi:"Bạn muốn ăn cái gì?"}],tables:null,exercises:null},{id:"hsk1_b6_g2",num:2,title:"Câu liên động (1): Chỉ Mục đích & Phương thức thực hiện",explanation:`Câu liên động là câu có từ hai động từ trở lên cùng chung một chủ ngữ. Trong HSK 1 gồm hai dạng chính:
1. Chỉ mục đích: Đi/đến đâu để làm gì (Hành động di chuyển trước, mục đích sau).
2. Chỉ phương thức: Đi bằng phương tiện gì đến đâu (Phương tiện/cách thức trước, hành động sau).`,formula:`Chỉ mục đích: S + 去 / 来 + Địa điểm + V2 + O
Chỉ phương thức: S + [Phương tiện/Cách thức] + V2 + [Địa điểm]`,note:"Các hành động trong câu liên động luôn diễn ra theo trình tự trước - sau theo thời gian thực tế.",examples:[{rawZh:"我去超市买东西。(Wǒ qù chāoshì mǎi dōngxi.)",zh:"我去超市买东西。",pinyin:"Wǒ qù chāoshì mǎi dōngxi.",vi:"Tôi đi siêu thị mua đồ (Mục đích)."},{rawZh:"他来学校学习。(Tā lái xuéxiào xuéxí.)",zh:"他来学校学习。",pinyin:"Tā lái xuéxiào xuéxí.",vi:"Anh ấy đến trường học tập (Mục đích)."},{rawZh:"下午我去电影院看电影。(Xiàwǔ wǒ qù diànyǐngyuàn kàn diànyǐng.)",zh:"下午我去电影院看电影。",pinyin:"Xiàwǔ wǒ qù diànyǐngyuàn kàn diànyǐng.",vi:"Buổi chiều tôi đi rạp chiếu phim xem phim (Mục đích)."},{rawZh:"我坐出租车去医院。(Wǒ zuò chūzūchē qù yīyuàn.)",zh:"我坐出租车去医院。",pinyin:"Wǒ zuò chūzūchē qù yīyuàn.",vi:"Tôi ngồi taxi đi bệnh viện (Phương thức)."},{rawZh:"他开车去超市。(Tā kāichē qù chāoshì.)",zh:"他开车去超市。",pinyin:"Tā kāichē qù chāoshì.",vi:"Anh ấy lái xe đi siêu thị (Phương thức)."}],tables:null,exercises:null},{id:"hsk1_b6_g3",num:3,title:"Đại từ nghi vấn “怎么” (Hỏi về cách thức thực hiện hành động)",explanation:'Đại từ nghi vấn "怎么" (zěnme) đứng trước động từ để hỏi về phương thức, phương tiện hoặc cách thức thực hiện của hành động đó (nghĩa là "làm như thế nào?", "đi bằng gì?").',formula:"Chủ ngữ + 怎么 + Động từ + (Tân ngữ)?",note:'Khác với "怎么样" (hỏi tính chất/trạng thái), "怎么" đứng trước động từ để hỏi cách làm.',examples:[{rawZh:"你怎么去学校？(Nǐ zěnme qù xuéxiào?)",zh:"你怎么去学校？",pinyin:"Nǐ zěnme qù xuéxiào?",vi:"Bạn đi đến trường bằng cách nào?"},{rawZh:"你怎么去超市？(Nǐ zěnme qù chāoshì?)",zh:"你怎么去超市？",pinyin:"Nǐ zěnme qù chāoshì?",vi:"Bạn đi siêu thị bằng cách nào?"},{rawZh:"这个电脑怎么买？(Zhège diànnǎo zěnme mǎi?)",zh:"这个电脑怎么买？",pinyin:"Zhège diànnǎo zěnme mǎi?",vi:"Máy tính này mua như thế nào?"}],tables:null,exercises:null}]},{lessonId:7,lessonKey:"Bài 7",lessonTitleZh:"我晚上六点半下班",lessonTitleFull:"Bài 7: 我晚上六点半下班 (Thời gian Giờ Phút, Trợ từ 吧, Vị trí Trạng ngữ, Trợ từ 呢 (2))",grammarPoints:[{id:"hsk1_b7_g1",num:1,title:"Cách diễn đạt Thời gian (2): Giờ, Phút & Các buổi trong ngày",explanation:`a. Dùng 点 (diǎn - giờ) và 分 (fēn - phút): Khi nói giờ rưỡi dùng 半 (bàn); khi phút nhỏ hơn 10 (từ 1 đến 9) bắt buộc chèn chữ 零 (líng).
b. Các buổi trong ngày: 上午 (sáng), 中午 (trưa), 下午 (chiều), 晚上 (tối). Từ chỉ buổi luôn đứng trước giờ cụ thể.`,formula:"[Buổi trong ngày] + [Số giờ] 点 + [Số phút] 分 (hoặc 半 / 零 [Số phút] 分)",note:"Ví dụ: 6:30 -> 六点半 (liù diǎn bàn); 8:05 -> 八点零五分 (bā diǎn líng wǔ fēn).",examples:[{rawZh:"六点半 (liù diǎn bàn)",zh:"六点半",pinyin:"liù diǎn bàn",vi:"6 giờ 30 phút / 6 rưỡi"},{rawZh:"八点零五分 (bā diǎn líng wǔ fēn)",zh:"八点零五分",pinyin:"bā diǎn líng wǔ fēn",vi:"8 giờ 5 phút"},{rawZh:"晚上八点我下班。(Wǎnshang bā diǎn wǒ xiàbān.)",zh:"晚上八点我下班。",pinyin:"Wǎnshang bā diǎn wǒ xiàbān.",vi:"8 giờ tối tôi tan làm."},{rawZh:"我下午去看电影。(Wǒ xiàwǔ qù kàn diànyǐng.)",zh:"我下午去看电影。",pinyin:"Wǒ xiàwǔ qù kàn diànyǐng.",vi:"Chiều nay tôi đi xem phim."}],tables:null,exercises:null},{id:"hsk1_b7_g2",num:2,title:"Trợ từ ngữ khí “吧” (1) - Đề nghị, gợi ý, rủ rê",explanation:'Trợ từ ngữ khí "吧" (ba) đặt ở cuối câu để biểu thị lời đề nghị, rủ rê, khuyên nhủ hoặc yêu cầu người nghe cùng thực hiện hành động một cách nhẹ nhàng (dịch là: "...nhé", "...đi", "...thôi").',formula:"Chủ ngữ + Động từ + Tân ngữ + 吧",note:"Ngữ khí nhẹ nhàng hơn rất nhiều so với câu mệnh lệnh trực tiếp.",examples:[{rawZh:"我们去超市吧。(Wǒmen qù chāoshì ba.)",zh:"我们去超市吧。",pinyin:"Wǒmen qù chāoshì ba.",vi:"Chúng ta đi siêu thị nhé!"},{rawZh:"明天我们去书店吧。(Míngtiān wǒmen qù shūdiàn ba.)",zh:"明天我们去书店吧。",pinyin:"Míngtiān wǒmen qù shūdiàn ba.",vi:"Ngày mai chúng ta đi hiệu sách nhé!"},{rawZh:"我们吃饭吧。(Wǒmen chīfàn ba.)",zh:"我们吃饭吧。",pinyin:"Wǒmen chīfàn ba.",vi:"Chúng ta ăn cơm thôi/đi!"}],tables:null,exercises:null},{id:"hsk1_b7_g3",num:3,title:"Vị trí của Phó từ & Từ ngữ chỉ thời gian khi làm trạng ngữ",explanation:`1. Phó từ (不, 很, 也...): Luôn đứng trước Động từ hoặc Tính từ mà nó bổ nghĩa.
2. Trạng ngữ chỉ thời gian (昨天, 今天, 明天...): Đứng trước Động từ (trước hoặc sau Chủ ngữ). Tuyệt đối không đứng cuối câu.
3. Khi có cả Thời gian và Địa điểm: Thời gian luôn đứng trước Địa điểm.`,formula:"Chủ ngữ + (Thời gian) + Phó từ + (在 + Địa điểm) + Động từ + Tân ngữ",note:"Trật tự vàng: Thời gian -> Địa điểm -> Động từ.",examples:[{rawZh:"他不喜欢包子。(Tā bù xǐhuan bāozi.)",zh:"他不喜欢包子。",pinyin:"Tā bù xǐhuan bāozi.",vi:"Anh ấy không thích bánh bao."},{rawZh:"我昨天在学校学习。(Wǒ zuótiān zài xuéxiào xuéxí.)",zh:"我昨天在学校学习。",pinyin:"Wǒ zuótiān zài xuéxiào xuéxí.",vi:"Hôm qua tôi học ở trường."},{rawZh:"今天我去超市。(Jīntiān wǒ qù chāoshì.)",zh:"今天我去超市。",pinyin:"Jīntiān wǒ qù chāoshì.",vi:"Hôm nay tôi đi siêu thị."},{rawZh:"明天我买手机。(Míngtiān wǒ mǎi shǒujī.)",zh:"明天我买手机。",pinyin:"Míngtiān wǒ mǎi shǒujī.",vi:"Ngày mai tôi mua điện thoại."}],tables:null,exercises:null},{id:"hsk1_b7_g4",num:4,title:"Trợ từ ngữ khí “呢” (2) - Khẳng định sự thực khách quan / Nhấn mạnh",explanation:'Trợ từ "呢" (ne) đặt ở cuối câu trần thuật dùng để khẳng định một sự thực, thông tin khách quan mà người nói muốn nhấn mạnh với người nghe.',formula:"Chủ ngữ + Vị ngữ + 呢",note:"Giúp câu nói thêm phần sinh động, tự nhiên và mang tính tương tác cao trong khẩu ngữ.",examples:[{rawZh:"我明天下午两点还上课呢。(Wǒ míngtiān xiàwǔ liǎng diǎn hái shàngkè ne.)",zh:"我明天下午两点还上课呢。",pinyin:"Wǒ míngtiān xiàwǔ liǎng diǎn hái shàngkè ne.",vi:"Chiều mai 2 giờ tôi vẫn còn phải lên lớp đấy nhé."},{rawZh:"妹妹会做两三个菜呢。(Mèimei huì zuò liǎng sān gè cài ne.)",zh:"妹妹会做两三个菜呢。",pinyin:"Mèimei huì zuò liǎng sān gè cài ne.",vi:"Em gái còn biết nấu hai ba món ăn cơ đấy."}],tables:null,exercises:null}]},{lessonId:8,lessonKey:"Bài 8",lessonTitleZh:"我爸爸也在医院工作",lessonTitleFull:"Bài 8: 我爸爸也在医院工作 (Phương vị từ, Giới từ 在 & Động từ năng nguyện 能)",grammarPoints:[{id:"hsk1_b8_g1",num:1,title:"Phương vị từ (Từ chỉ vị trí và phương hướng)",explanation:'Phương vị từ trong tiếng Trung đứng sau danh từ để tạo thành cụm từ chỉ vị trí của sự vật. Có thể thêm hậu tố "边" (biān) hoặc "面" (miàn) vào sau để chỉ phương hướng rõ ràng hơn.',formula:"[Danh từ] + [Phương vị từ]",note:"Các phương vị từ thường gặp: 上 (trên), 下 (dưới), 里 (trong), 外 (ngoài), 前 (trước), 后 (sau).",examples:[{rawZh:"桌子上 (Zhuōzi shàng)",zh:"桌子上",pinyin:"Zhuōzi shàng",vi:"Trên bàn"},{rawZh:"桌子下 (Zhuōzi xià)",zh:"桌子下",pinyin:"Zhuōzi xià",vi:"Dưới bàn"},{rawZh:"房间里 (Fángjiān lǐ)",zh:"房间里",pinyin:"Fángjiān lǐ",vi:"Trong phòng"},{rawZh:"房间外 (Fángjiān wài)",zh:"房间外",pinyin:"Fángjiān wài",vi:"Ngoài phòng"},{rawZh:"超市前 (Chāoshì qián)",zh:"超市前",pinyin:"Chāoshì qián",vi:"Trước siêu thị (hoặc: 超市前边 Chāoshì qiánbian)"},{rawZh:"家后 (Jiā hòu)",zh:"家后",pinyin:"Jiā hòu",vi:"Sau nhà (hoặc: 家后边 Jiā hòubian)"}],tables:[{title:"Bảng các Phương vị từ thường gặp (HSK 1)",headers:["Phương vị từ","Nghĩa tiếng Việt","Ví dụ ghép cụm từ","Dịch nghĩa"],rows:[["上 (shàng)","Trên","桌子上 (Zhuōzi shàng)","Trên bàn"],["下 (xià)","Dưới","桌子下 (Zhuōzi xià)","Dưới bàn"],["里 (lǐ)","Trong","房间里 (Fángjiān lǐ)","Trong phòng"],["外 (wài)","Ngoài","房间外 (Fángjiān wài)","Ngoài phòng"],["前 (qián)","Trước","超市前 (Chāoshì qián)","Trước siêu thị"],["后 (hòu)","Sau","家后 (Jiā hòu)","Sau nhà"]]}],exercises:null},{id:"hsk1_b8_g2",num:2,title:"Giới từ “在” (Chỉ vị trí & Nơi chốn diễn ra hành động)",explanation:`Giới từ "在" (zài) có hai cách dùng chính:
1. Đóng vai trò làm Động từ chính: Biểu thị người/vật đang ở vị trí nào (ở đâu).
2. Đóng vai trò làm Giới từ chỉ nơi chốn: Kết hợp với địa điểm đứng trước động từ để biểu thị hành động diễn ra ở đâu (làm gì ở đâu).`,formula:`1. Chỉ vị trí: S + (不)在 + Địa điểm
2. Nơi chốn hành động: S + 在 + Địa điểm + V + O`,note:"Khi phủ định câu nơi chốn hành động: S + 不在 + Địa điểm + V + O.",examples:[{rawZh:"他在学校。(Tā zài xuéxiào.)",zh:"他在学校。",pinyin:"Tā zài xuéxiào.",vi:"Anh ấy ở trường."},{rawZh:"我不在家。(Wǒ bú zài jiā.)",zh:"我不在家。",pinyin:"Wǒ bú zài jiā.",vi:"Tôi không có ở nhà."},{rawZh:"我在房间里看电影。(Wǒ zài fángjiān lǐ kàn diànyǐng.)",zh:"我在房间里看电影。",pinyin:"Wǒ zài fángjiān lǐ kàn diànyǐng.",vi:"Tôi xem phim ở trong phòng."},{rawZh:"我昨天在学校学习。(Wǒ zuótiān zài xuéxiào xuéxí.)",zh:"我昨天在学校学习。",pinyin:"Wǒ zuótiān zài xuéxiào xuéxí.",vi:"Hôm qua tôi học ở trường."},{rawZh:"他在医院工作。(Tā zài yīyuàn gōngzuò.)",zh:"他在医院工作。",pinyin:"Tā zài yīyuàn gōngzuò.",vi:"Anh ấy làm việc ở bệnh viện."}],tables:null,exercises:null},{id:"hsk1_b8_g3",num:3,title:"Động từ năng nguyện “能” (Biểu thị Khả năng & Sự cho phép)",explanation:`Động từ năng nguyện "能" (néng) dùng để:
1. Biểu thị điều kiện khách quan, năng lực có thể làm được việc gì.
2. Biểu thị sự xin phép hoặc cấp phép (nghĩa là "có thể").`,formula:`Khẳng định: S + 能 + V + O
Phủ định: S + 不能 + V + O
Nghi vấn: S + 能 + V + O + 吗?`,note:'Khi biểu thị sự cấm đoán, không được phép làm gì, dùng "不能" (bù néng).',examples:[{rawZh:"我明天能去超市。(Wǒ míngtiān néng qù chāoshì.)",zh:"我明天能去超市。",pinyin:"Wǒ míngtiān néng qù chāoshì.",vi:"Ngày mai tôi có thể đi siêu thị."},{rawZh:"我能问你一个问题吗？(Wǒ néng wèn nǐ yí gè wèntí ma?)",zh:"我能问你一个问题吗？",pinyin:"Wǒ néng wèn nǐ yí gè wèntí ma?",vi:"Tôi có thể hỏi bạn một câu hỏi được không?"},{rawZh:"你不能在这里看电影。(Nǐ bù néng zài zhèlǐ kàn diànyǐng.)",zh:"你不能在这里看电影。",pinyin:"Nǐ bù néng zài zhèlǐ kàn diànyǐng.",vi:"Bạn không thể xem phim ở đây."}],tables:null,exercises:null}]},{lessonId:9,lessonKey:"Bài 9",lessonTitleZh:"我明天上午在学校学习",lessonTitleFull:"Bài 9: 我明天上午在学校学习 (Câu tồn hiện 有/是, Trật tự Trạng ngữ & Số thứ tự 第)",grammarPoints:[{id:"hsk1_b9_g1",num:1,title:"Câu tồn hiện (1): Với “有” (Biểu thị tồn tại) & Với “是” (Biểu thị xác định)",explanation:`Câu tồn hiện dùng để thông báo về sự tồn tại hoặc xuất hiện của người/vật tại một địa điểm:
1. Với "有": Tại địa điểm có người/vật nào đó (chưa xác định cụ thể).
2. Với "是": Tại địa điểm chính là người/vật cụ thể đó.`,formula:`Với 有: [Địa điểm] + 有 + [Số lượng / Lượng từ] + [Danh từ]
Với 是: [Địa điểm] + 是 + [Danh từ]`,note:'Sau "有" thường là tân ngữ không xác định (有一只猫); sau "是" thường là danh từ xác định (是学校, 是我家).',examples:[{rawZh:"房间里有一只小猫。(Fángjiān lǐ yǒu yì zhī xiǎo māo.)",zh:"房间里有一只小猫。",pinyin:"Fángjiān lǐ yǒu yì zhī xiǎo māo.",vi:"Trong phòng có một con mèo nhỏ."},{rawZh:"超市前有一家电影院。(Chāoshì qián yǒu yì jiā diànyǐngyuàn.)",zh:"超市前有一家电影院。",pinyin:"Chāoshì qián yǒu yì jiā diànyǐngyuàn.",vi:"Trước siêu thị có một rạp chiếu phim."},{rawZh:"医院里有很多病人。(Yīyuàn lǐ yǒu hěn duō bìngrén.)",zh:"医院里有很多病人。",pinyin:"Yīyuàn lǐ yǒu hěn duō bìngrén.",vi:"Trong bệnh viện có rất nhiều bệnh nhân."},{rawZh:"桌子上有一本书。(Zhuōzi shàng yǒu yì běn shū.)",zh:"桌子上有一本书。",pinyin:"Zhuōzi shàng yǒu yì běn shū.",vi:"Trên bàn có một quyển sách."},{rawZh:"前边是学校。(Qiánbian shì xuéxiào.)",zh:"前边是学校。",pinyin:"Qiánbian shì xuéxiào.",vi:"Phía trước chính là trường học."},{rawZh:"超市前是我的家。(Chāoshì qián shì wǒ de jiā.)",zh:"超市前是我的家。",pinyin:"Chāoshì qián shì wǒ de jiā.",vi:"Trước siêu thị là nhà của tôi."},{rawZh:"那儿是我的房间。(Nàr shì wǒ de fángjiān.)",zh:"那儿是我的房间。",pinyin:"Nàr shì wǒ de fángjiān.",vi:"Chỗ kia là phòng của tôi."}],tables:null,exercises:null},{id:"hsk1_b9_g2",num:2,title:"Trật tự ưu tiên của Trạng ngữ Thời gian và Nơi chốn",explanation:"Khi trong một câu xuất hiện đồng thời cả trạng ngữ chỉ thời gian và trạng ngữ chỉ địa điểm, trật tự chuẩn mực luôn là: Thời gian đứng TRƯỚC Địa điểm.",formula:"(Chủ ngữ) + [Thời gian] + (Chủ ngữ) + [在 + Địa điểm] + [Động từ] + [Tân ngữ]",note:"Mẹo ghi nhớ logic tư duy tiếng Trung: Khi nào? (Thời gian) -> Ở đâu? (Địa điểm) -> Làm gì? (Hành động).",examples:[{rawZh:"我昨天在学校学习。(Wǒ zuótiān zài xuéxiào xuéxí.)",zh:"我昨天在学校学习。",pinyin:"Wǒ zuótiān zài xuéxiào xuéxí.",vi:"Hôm qua tôi học ở trường."},{rawZh:"明天我去超市。(Míngtiān wǒ qù chāoshì.)",zh:"明天我去超市。",pinyin:"Míngtiān wǒ qù chāoshì.",vi:"Ngày mai tôi đi siêu thị."},{rawZh:"晚上八点我在医院下班。(Wǎnshang bā diǎn wǒ zài yīyuàn xiàbān.)",zh:"晚上八点我在医院下班。",pinyin:"Wǎnshang bā diǎn wǒ zài yīyuàn xiàbān.",vi:"8 giờ tối tôi tan làm ở bệnh viện."}],tables:null,exercises:null},{id:"hsk1_b9_g3",num:3,title:"Tiền tố “第” (dì) dùng để biểu thị số thứ tự",explanation:'Tiền tố "第" (dì) đặt trước số từ để tạo thành số thứ tự (ví dụ: thứ nhất, thứ hai, bài một...).',formula:"第 (dì) + Số từ + (Lượng từ) + Danh từ",note:'Khi nói "bài 1" dùng 第一课 (không cần lượng từ); khi nói "người thứ nhất" dùng 第一个人 (cần lượng từ).',examples:[{rawZh:"第一课 (dì-yī kè)",zh:"第一课",pinyin:"dì-yī kè",vi:"Bài học số 1 / Bài thứ nhất"},{rawZh:"第二楼 (dì-èr lóu)",zh:"第二楼",pinyin:"dì-èr lóu",vi:"Tầng 2"},{rawZh:"第三个 (dì-sān gè)",zh:"第三个",pinyin:"dì-sān gè",vi:"Cái thứ 3"}],tables:null,exercises:null}]},{lessonId:10,lessonKey:"Bài 10",lessonTitleZh:"这儿的苹果真便宜！",lessonTitleFull:"Bài 10: 这儿的苹果真便宜！ (Diễn đạt tiền tệ, Câu vị ngữ tính từ & Đại từ 怎么样)",grammarPoints:[{id:"hsk1_b10_g1",num:1,title:"Cách diễn đạt số tiền trong tiếng Trung",explanation:`Tiền tệ Trung Quốc gồm hai hình thức: Khẩu ngữ và Văn viết.
- Đơn vị chính: 块 (kuài - nói) / 元 (yuán - viết).
- Đơn vị 1/10 (hào): 毛 (máo - nói) / 角 (jiǎo - viết).
- Đơn vị 1/100 (xu): 分 (fēn).
Quy tắc quy đổi: 1 块 = 10 毛, 1 毛 = 10 分.`,formula:"[Số] 块 + ( [Số] 毛 ) + ( [Số] 分 )",note:`Lưu ý:
1. Khẩu ngữ hay lược bỏ từ 毛 nếu phía sau có số khác (Ví dụ: 1.5 tệ đọc là 1块5).
2. Khi có số 0 ở hàng hào (như 1.05 tệ), phải thêm "零" (1块零5分).
3. Số 2 đứng trước đơn vị tiền tệ thường đọc là "两" (2.5 tệ -> 两块五).`,examples:[{rawZh:"3块 (Sān kuài) - 3 tệ",zh:"3块",pinyin:"sān kuài",vi:"3 tệ (Khẩu ngữ)"},{rawZh:"1块5 (Yī kuài wǔ) - 1.5 tệ",zh:"1块5",pinyin:"yí kuài wǔ",vi:"1 đồng 5 hào (1.5 tệ)"},{rawZh:"2块8 (Liǎng kuài bā) - 2.8 tệ",zh:"2块8",pinyin:"liǎng kuài bā",vi:"2 đồng 8 hào (2.8 tệ)"},{rawZh:"1块5毛5 (Yī kuài wǔ máo wǔ fēn) - 1.55 tệ",zh:"1块5毛5",pinyin:"yí kuài wǔ máo wǔ fēn",vi:"1 đồng 5 hào 5 xu (1.55 tệ)"},{rawZh:"1块零5分 (Yī kuài líng wǔ fēn) - 1.05 tệ",zh:"1块零5分",pinyin:"yí kuài líng wǔ fēn",vi:"1 đồng 0 hào 5 xu (1.05 tệ)"}],tables:[{title:"Bảng phân cấp đơn vị tiền tệ Trung Quốc",headers:["Đơn vị","Văn nói (Khẩu ngữ)","Văn viết (Trang trọng)","Giá trị quy đổi"],rows:[["Đơn vị chính","块 (kuài)","元 (yuán)","1 đơn vị tệ"],["Đơn vị 1/10","毛 (máo)","角 (jiǎo)","0.1 đơn vị (Hào)"],["Đơn vị 1/100","分 (fēn)","分 (fēn)","0.01 đơn vị (Xu)"]]}],exercises:null},{id:"hsk1_b10_g2",num:2,title:"Câu vị ngữ tính từ (Không dùng động từ “是”)",explanation:'Trong tiếng Trung, tính từ có thể trực tiếp làm vị ngữ. Trước tính từ thường thêm các phó từ chỉ mức độ (很, 真, 非常, 太) hoặc phó từ phủ định (不). Giữa Chủ ngữ và Tính từ TUYỆT ĐỐI KHÔNG dùng "是".',formula:`Khẳng định: Chủ ngữ + (Phó từ mức độ: 很 / 真 / 非常) + Tính từ
Phủ định: Chủ ngữ + 不 + Tính từ`,note:'Nếu dùng câu trần thuật không có phó từ mức độ (như "那个苹果好吃"), câu sẽ mang sắc thái so sánh ngầm.',examples:[{rawZh:"那个苹果好吃。(Nàge píngguǒ hǎochī.)",zh:"那个苹果好吃。",pinyin:"Nàge píngguǒ hǎochī.",vi:"Quả táo kia ngon."},{rawZh:"我不忙。(Wǒ bù máng.)",zh:"我不忙。",pinyin:"Wǒ bù máng.",vi:"Tôi không bận."},{rawZh:"你忙吗？(Nǐ máng ma?)",zh:"你忙吗？",pinyin:"Nǐ máng ma?",vi:"Bạn có bận không?"}],tables:null,exercises:null},{id:"hsk1_b10_g3",num:3,title:"Đại từ nghi vấn “怎么样” (Hỏi tình hình, tính chất hoặc xin ý kiến)",explanation:`Đại từ nghi vấn "怎么样" (zěnmeyàng) thường đặt ở cuối câu dùng để:
1. Hỏi về tính chất, trạng thái, tình hình sức khỏe, công việc ("...thế nào?").
2. Đưa ra gợi ý, đề xuất và xin ý kiến người nghe ("...được không?", "...nhé?").`,formula:`1. Hỏi tình hình: Chủ ngữ + 怎么样?
2. Đề xuất ý kiến: [Mệnh đề câu] + ，怎么样?`,note:"Trong khẩu ngữ rất thường xuyên sử dụng.",examples:[{rawZh:"这个杯子怎么样？(Zhège bēizi zěnmeyàng?)",zh:"这个杯子怎么样？",pinyin:"Zhège bēizi zěnmeyàng?",vi:"Cái cốc này thế nào?"},{rawZh:"这件衣服怎么样？(Zhè jiàn yīfu zěnmeyàng?)",zh:"这件衣服怎么样？",pinyin:"Zhè jiàn yīfu zěnmeyàng?",vi:"Bộ quần áo này thế nào?"},{rawZh:"我们去看电影，怎么样？(Wǒmen qù kàn diànyǐng, zěnmeyàng?)",zh:"我们去看电影，怎么样？",pinyin:"Wǒmen qù kàn diànyǐng, zěnmeyàng?",vi:"Chúng ta đi xem phim nhé, được không?"}],tables:null,exercises:null}]},{lessonId:11,lessonKey:"Bài 11",lessonTitleZh:"我读大学了",lessonTitleFull:"Bài 11: 我读大学了 (Câu hỏi chính phản, Phó từ 在/正在 & Động từ năng nguyện 要)",grammarPoints:[{id:"hsk1_b11_g1",num:1,title:"Câu hỏi chính phản (V/Adj + 不/没 + V/Adj)",explanation:"Câu hỏi chính phản được tạo thành bằng cách ghép hình thức khẳng định và phủ định của động từ hoặc tính từ liền kề nhau để tạo câu hỏi lựa chọn Có/Không.",formula:`Với động từ: Chủ ngữ + V + 不 / 没 + V + (Tân ngữ)?
Với tính từ: Chủ ngữ + Adj + 不 + Adj?`,note:'LƯU Ý CỰC KỲ QUAN TRỌNG: Khi đã sử dụng câu hỏi chính phản thì TUYỆT ĐỐI KHÔNG dùng trợ từ "吗" ở cuối câu.',examples:[{rawZh:"你想不想去超市？(Nǐ xiǎng bu xiǎng qù chāoshì?)",zh:"你想不想去超市？",pinyin:"Nǐ xiǎng bu xiǎng qù chāoshì?",vi:"Bạn có muốn đi siêu thị không?"},{rawZh:"你去没去学校？(Nǐ qù méi qù xuéxiào?)",zh:"你去没去学校？",pinyin:"Nǐ qù méi qù xuéxiào?",vi:"Bạn đã đi đến trường chưa?"},{rawZh:"这件衣服好看不好看？(Zhè jiàn yīfu hǎokàn bu hǎokàn?)",zh:"这件衣服好看不好看？",pinyin:"Zhè jiàn yīfu hǎokàn bu hǎokàn?",vi:"Bộ quần áo này đẹp hay không đẹp?"}],tables:null,exercises:null},{id:"hsk1_b11_g2",num:2,title:"Phó từ chỉ thời gian “在 / 正在” (Biểu thị hành động đang diễn ra)",explanation:`Dùng để diễn tả hành động đang diễn ra tại thời điểm nói (tương đương nghĩa "đang" trong tiếng Việt).
- 正在 (zhèngzài): Nhấn mạnh hành động đang diễn ra ngay lúc này.
- 在 (zài): Mô tả hành động đang tiếp diễn.`,formula:`Khẳng định: Chủ ngữ + (正在 / 在) + Động từ + (Tân ngữ) + (呢)
Phủ định: Chủ ngữ + 没 (有) + (在) + Động từ + (Tân ngữ)`,note:'Khi phủ định hành động đang diễn ra, BẮT BUỘC dùng "没 / 没有", TUYỆT ĐỐI không dùng "不".',examples:[{rawZh:"他正在看书呢。(Tā zhèngzài kàn shū ne.)",zh:"他正在看书呢。",pinyin:"Tā zhèngzài kàn shū ne.",vi:"Anh ấy đang đọc sách."},{rawZh:"我在吃饭。(Wǒ zài chīfàn.)",zh:"我在吃饭。",pinyin:"Wǒ zài chīfàn.",vi:"Tôi đang ăn cơm."},{rawZh:"我没有在睡觉。(Wǒ méiyǒu zài shuìjiào.)",zh:"我没有在睡觉。",pinyin:"Wǒ méiyǒu zài shuìjiào.",vi:"Tôi không có đang ngủ."}],tables:null,exercises:null},{id:"hsk1_b11_g3",num:3,title:"Động từ năng nguyện “要” (Biểu thị Mong muốn mạnh mẽ / Kế hoạch)",explanation:'Động từ năng nguyện "要" (yào) đứng trước động từ để biểu thị ý định, mong muốn mạnh mẽ hoặc một kế hoạch chắc chắn sẽ thực hiện trong tương lai gần.',formula:"Chủ ngữ + 要 + Động từ + Tân ngữ",note:'Sắc thái của "要" mang tính quyết tâm và chủ động mạnh mẽ hơn so với "想".',examples:[{rawZh:"他今天要和小朋友玩。(Tā jīntiān yào hé xiǎopéngyou wán.)",zh:"他今天要和小朋友玩。",pinyin:"Tā jīntiān yào hé xiǎopéngyou wán.",vi:"Hôm nay cậu ấy sẽ/muốn chơi cùng các bạn nhỏ."},{rawZh:"妈妈要去超市。(Māma yào qù chāoshì.)",zh:"妈妈要去超市。",pinyin:"Māma yào qù chāoshì.",vi:"Mẹ sẽ đi siêu thị."}],tables:null,exercises:null}]},{lessonId:12,lessonKey:"Bài 12",lessonTitleZh:"昨天下雪了",lessonTitleFull:"Bài 12: 昨天下雪了 (Câu phi chủ vị, Trợ từ ngữ khí 了 (1) & Cấu trúc 太……了)",grammarPoints:[{id:"hsk1_b12_g1",num:1,title:"Câu phi chủ vị (Câu không có thành phần chủ ngữ)",explanation:"Câu phi chủ vị là loại câu không thể và không cần xác định thành phần Chủ ngữ - Vị ngữ, thường dùng để diễn tả các hiện tượng thời tiết tự nhiên, sự chuyển biến môi trường hoặc dùng làm câu cảm thán, lời chào, hiệu lệnh.",formula:"[Động từ / Cụm vị ngữ] + (Tân ngữ / Trợ từ)",note:"Ví dụ phổ biến: 下雨了 (Mưa rồi), 下雪了 (Tuyết rơi rồi), 上课了 (Vào học rồi).",examples:[{rawZh:"下雨了。(Xiàyǔ le.)",zh:"下雨了。",pinyin:"Xiàyǔ le.",vi:"Trời mưa rồi."},{rawZh:"下雪了。(Xiàxuě le.)",zh:"下雪了。",pinyin:"Xiàxuě le.",vi:"Tuyết rơi rồi."},{rawZh:"上课了。(Shàngkè le.)",zh:"上课了。",pinyin:"Shàngkè le.",vi:"Đến giờ vào học rồi."},{rawZh:"真漂亮！(Zhēn piàoliang!)",zh:"真漂亮！",pinyin:"Zhēn piàoliang!",vi:"Đẹp thật đấy!"}],tables:null,exercises:null},{id:"hsk1_b12_g2",num:2,title:"Trợ từ ngữ khí “了” (1) - Biểu thị sự thay đổi trạng thái",explanation:'Trợ từ ngữ khí "了" (1) đặt ở CUỐI CÂU dùng để diễn tả một tình huống mới phát sinh hoặc có sự thay đổi về trạng thái (tương đương "rồi" trong tiếng Việt).',formula:`Khẳng định: Chủ ngữ + Vị ngữ + 了
Phủ định: Chủ ngữ + 没 (有) + Vị ngữ (BẮT BUỘC BỎ "了")`,note:'Quy tắc phủ định: Khi chuyển sang câu phủ định, bắt buộc dùng "没(有)" và PHẢI BỎ trợ từ "了" ở cuối câu.',examples:[{rawZh:"下雨了。(Xiàyǔ le.) -> 没下雨。(Méi xiàyǔ.)",zh:"下雨了。",pinyin:"Xiàyǔ le.",vi:"Trời mưa rồi (trước đó không mưa) -> Phủ định: 没下雨 (Chưa mưa)."},{rawZh:"我生病了。(Wǒ shēngbìng le.)",zh:"我生病了。",pinyin:"Wǒ shēngbìng le.",vi:"Tôi bị ốm rồi (trước đó khỏe)."},{rawZh:"我吃饭了。(Wǒ chīfàn le.) -> 我没吃饭。(Wǒ méi chīfàn.)",zh:"我吃饭了。",pinyin:"Wǒ chīfàn le.",vi:"Tôi ăn cơm rồi -> Phủ định: 我没吃饭 (Tôi chưa ăn cơm)."}],tables:null,exercises:null},{id:"hsk1_b12_g3",num:3,title:"Cấu trúc cảm thán “太……了” (Biểu thị mức độ cao)",explanation:'Cấu trúc "太……了" (tài... le) dùng để biểu thị mức độ rất cao, thường dùng trong câu cảm thán để bày tỏ cảm xúc hài lòng, khen ngợi hoặc phàn nàn của người nói (nghĩa là: "...quá!", "...lắm!").',formula:"Chủ ngữ + 太 + Tính từ + 了",note:'Khi phủ định (không... lắm) dùng "不太 + Tính từ" và không có "了" ở cuối (Ví dụ: 不太好 - Không tốt lắm).',examples:[{rawZh:"太好了！(Tài hǎo le!)",zh:"太好了！",pinyin:"Tài hǎo le!",vi:"Tốt quá! / Tuyệt vời quá!"},{rawZh:"太漂亮了！(Tài piàoliang le!)",zh:"太漂亮了！",pinyin:"Tài piàoliang le!",vi:"Đẹp quá!"},{rawZh:"太贵了！(Tài guì le!)",zh:"太贵了！",pinyin:"Tài guì le!",vi:"Đắt quá!"},{rawZh:"太冷了！(Tài lěng le!)",zh:"太冷了！",pinyin:"Tài lěng le!",vi:"Lạnh quá!"}],tables:null,exercises:null}]},{lessonId:13,lessonKey:"Bài 13",lessonTitleZh:"请给我一杯茶",lessonTitleFull:"Bài 13: 请给我一杯茶 (Động từ năng nguyện 可以, Cấu trúc V+一下 & Câu hai tân ngữ)",grammarPoints:[{id:"hsk1_b13_g1",num:1,title:"Động từ năng nguyện “可以” (Sự cho phép & Khả năng)",explanation:'Động từ năng nguyện "可以" (kěyǐ) trong tiếng Trung có nghĩa là "có thể / được phép", dùng để biểu thị sự cho phép hoặc hỏi xin phép người khác một cách lịch sự.',formula:`Khẳng định: S + 可以 + V + O
Phủ định: S + 不可以 + V + O
Nghi vấn: S + 可以 + V + O + 吗?`,note:'Khi từ chối hoặc cấm đoán, dùng "不可以" (không được phép).',examples:[{rawZh:"我可以问你一个问题吗？(Wǒ kěyǐ wèn nǐ yí gè wèntí ma?)",zh:"我可以问你一个问题吗？",pinyin:"Wǒ kěyǐ wèn nǐ yí gè wèntí ma?",vi:"Tôi có thể hỏi bạn một câu hỏi được không?"},{rawZh:"我可以坐这儿吗？(Wǒ kěyǐ zuò zhèr ma?)",zh:"我可以坐这儿吗？",pinyin:"Wǒ kěyǐ zuò zhèr ma?",vi:"Tôi có thể ngồi ở đây không?"},{rawZh:"这儿不可以睡觉。(Zhèr bù kěyǐ shuìjiào.)",zh:"这儿不可以睡觉。",pinyin:"Zhèr bù kěyǐ shuìjiào.",vi:"Ở đây không được phép ngủ."},{rawZh:"你可以给我打个电话。(Nǐ kěyǐ gěi wǒ dǎ gè diànhuà.)",zh:"你可以给我打个电话。",pinyin:"Nǐ kěyǐ gěi wǒ dǎ gè diànhuà.",vi:"Bạn có thể gọi điện thoại cho tôi."}],tables:null,exercises:null},{id:"hsk1_b13_g2",num:2,title:"Cấu trúc “Động từ + 一下” (Làm mềm ngữ khí, lịch sự)",explanation:'Cấu trúc "Động từ + 一下" (yíxià) dùng để làm mềm ngữ khí, biểu thị hành động diễn ra trong thời gian ngắn hoặc mang tính thử làm, giúp câu cầu khiến hoặc yêu cầu trở nên nhẹ nhàng, lịch sự và tự nhiên hơn.',formula:"Chủ ngữ + (可以 / 请) + Động từ + 一下",note:'Tương đương với từ "một chút / một lát / thử... xem" trong tiếng Việt.',examples:[{rawZh:"你可以打电话问一下。(Nǐ kěyǐ dǎ diànhuà wèn yíxià.)",zh:"你可以打电话问一下。",pinyin:"Nǐ kěyǐ dǎ diànhuà wèn yíxià.",vi:"Bạn có thể gọi điện thoại hỏi thử một chút."},{rawZh:"请休息一下。(Qǐng xiūxi yíxià.)",zh:"请休息一下。",pinyin:"Qǐng xiūxi yíxià.",vi:"Xin mời nghỉ ngơi một lát."},{rawZh:"你看一下。(Nǐ kàn yíxià.)",zh:"你看一下。",pinyin:"Nǐ kàn yíxià.",vi:"Bạn xem qua một chút đi."}],tables:null,exercises:null},{id:"hsk1_b13_g3",num:3,title:"Câu có hai tân ngữ (1): Với “给” (cho/đưa) & “问” (hỏi)",explanation:"Câu có hai tân ngữ là câu mà động từ kết hợp đồng thời với hai tân ngữ: Tân ngữ 1 chỉ người (tân ngữ gián tiếp, đứng trước) và Tân ngữ 2 chỉ sự vật / câu hỏi (tân ngữ trực tiếp, đứng sau).",formula:"Chủ ngữ + Động từ (给 / 问 / 教) + Tân ngữ chỉ người + Tân ngữ chỉ vật",note:"Trong HSK 1, hai động từ hai tân ngữ điển hình nhất là 给 (gěi - đưa/cho) và 问 (wèn - hỏi).",examples:[{rawZh:"请给我一杯茶。(Qǐng gěi wǒ yì bēi chá.)",zh:"请给我一杯茶。",pinyin:"Qǐng gěi wǒ yì bēi chá.",vi:"Xin cho tôi một ly trà (Người: 我, Vật: 一杯茶)."},{rawZh:"你可以给我打个电话。(Nǐ kěyǐ gěi wǒ dǎ gè diànhuà.)",zh:"你可以给我打个电话。",pinyin:"Nǐ kěyǐ gěi wǒ dǎ gè diànhuà.",vi:"Bạn có thể gọi cho tôi một cuộc điện thoại."},{rawZh:"我可以问你一个问题吗？(Wǒ kěyǐ wèn nǐ yí gè wèntí ma?)",zh:"我可以问你一个问题吗？",pinyin:"Wǒ kěyǐ wèn nǐ yí gè wèntí ma?",vi:"Tôi có thể hỏi bạn một câu hỏi được không? (Người: 你, Vật: 一个问题)."}],tables:null,exercises:null}]},{lessonId:14,lessonKey:"Bài 14",lessonTitleZh:"我看了一个电影",lessonTitleFull:"Bài 14: 我看了一个电影 (Trợ từ động thái 了 (2), Từ ly hợp & Phó từ phạm vi 都)",grammarPoints:[{id:"hsk1_b14_g1",num:1,title:"Trợ từ động thái “了” (2) - Biểu thị hành động đã hoàn thành",explanation:'Trợ từ động thái "了" (2) được đặt NGAY SAU ĐỘNG TỪ để biểu thị hành động đó đã xảy ra hoặc đã hoàn thành. Nếu phía sau có tân ngữ, tân ngữ thường có định ngữ hoặc số lượng từ bổ nghĩa.',formula:`Khẳng định: Chủ ngữ + Động từ + 了 + (Lượng từ/Định ngữ) + Tân ngữ
Phủ định: Chủ ngữ + 没 (有) + Động từ + Tân ngữ (BẮT BUỘC BỎ "了")
Nghi vấn: Chủ ngữ + Động từ + 了 + Tân ngữ + 没有 / 吗?`,note:`Phân biệt "了" (1) và "了" (2):
- 了 (1) đứng CUỐI CÂU (Bài 12): Chỉ sự thay đổi trạng thái (Ví dụ: 下雨了 - Trời mưa rồi).
- 了 (2) đứng NGAY SAU ĐỘNG TỪ (Bài 14): Chỉ hành động đã hoàn thành (Ví dụ: 我看了一个电影 - Tôi đã xem một bộ phim).`,examples:[{rawZh:"我看了一个电影。(Wǒ kàn le yí gè diànyǐng.)",zh:"我看了一个电影。",pinyin:"Wǒ kàn le yí gè diànyǐng.",vi:"Tôi đã xem một bộ phim."},{rawZh:"我买了新电脑。(Wǒ mǎi le xīn diànnǎo.)",zh:"我买了新电脑。",pinyin:"Wǒ mǎi le xīn diànnǎo.",vi:"Tôi đã mua máy tính mới."},{rawZh:"我没买新电脑。(Wǒ méi mǎi xīn diànnǎo.)",zh:"我没买新电脑。",pinyin:"Wǒ méi mǎi xīn diànnǎo.",vi:'Tôi chưa mua máy tính mới (Phủ định không dùng "了").'}],tables:null,exercises:null},{id:"hsk1_b14_g2",num:2,title:"Từ ly hợp (离合词) trong tiếng Trung (Cấu trúc V + O)",explanation:`Từ ly hợp là những từ có cấu tạo gồm 2 phần: Động từ (V) + Tân ngữ (O).
Nguyên tắc quan trọng:
1. Có thể tách rời: Khi thêm trợ từ động thái (le, guo), số lượng từ, thời lượng, PHẢI CHÈN VÀO GIỮA Động từ và Tân ngữ.
2. Không mang tân ngữ phía sau: Không được thêm một tân ngữ khác trực tiếp sau từ ly hợp.`,formula:"Động từ + (Trợ từ 了 / Số lượng từ / Thời lượng) + Tân ngữ của từ ly hợp",note:'Ví dụ: Không nói "睡觉八小时", phải nói "睡了八个小时觉" hoặc "睡觉睡了八个小时".',examples:[{rawZh:"睡觉 (shuìjiào - Đi ngủ) -> 睡了一觉 (Đã ngủ một giấc)",zh:"睡了一觉",pinyin:"shuì le yí jiào",vi:"Đã ngủ một giấc"},{rawZh:"吃饭 (chīfàn - Ăn cơm) -> 吃了一顿饭 (Đã ăn một bữa cơm)",zh:"吃了一顿饭",pinyin:"chī le yí dùn fàn",vi:"Đã ăn một bữa cơm"},{rawZh:"打电话 (dǎ diànhuà - Gọi điện) -> 打了个电话 (Đã gọi một cuộc điện thoại)",zh:"打了个电话",pinyin:"dǎ le gè diànhuà",vi:"Đã gọi một cuộc điện thoại"},{rawZh:"开车 (kāichē - Lái xe) -> 开了两小时车 (Đã lái xe 2 tiếng)",zh:"开了两小时车",pinyin:"kāi le liǎng xiǎoshí chē",vi:"Đã lái xe 2 tiếng"}],tables:[{title:"Bảng các Từ Ly Hợp thường gặp (HSK 1)",headers:["Từ ly hợp","Phiên âm","Ý nghĩa","Ví dụ tách từ (Chèn trợ từ/số lượng)"],rows:[["睡觉","shuìjiào","Đi ngủ","睡了一觉 (Đã ngủ một giấc)"],["吃饭","chīfàn","Ăn cơm","吃了一顿饭 (Đã ăn một bữa cơm)"],["打电话","dǎ diànhuà","Gọi điện","打了个电话 (Đã gọi một cuộc điện thoại)"],["开车","kāichē","Lái xe","开了两小时车 (Đã lái xe 2 tiếng)"],["上课","shàngkè","Lên lớp","上了一节课 (Đã lên một tiết học)"],["下班","xiàbān","Tan làm","下了班 (Đã tan làm)"],["做饭","zuòfàn","Nấu ăn","做了很多饭 (Đã nấu rất nhiều cơm)"]]}],exercises:null},{id:"hsk1_b14_g3",num:3,title:'Phó từ chỉ phạm vi “都” (Biểu thị ý nghĩa "Đều")',explanation:'Phó từ "都" (dōu) có nghĩa là "đều", dùng để tổng kết hoặc bao quát toàn bộ đối tượng được nhắc đến trong câu.',formula:"Chủ ngữ (bắt buộc số nhiều) + 都 + (不) + Động từ / Tính từ",note:`Lưu ý:
1. Chủ ngữ đi kèm "都" bắt buộc phải là dạng SỐ NHIỀU (Chúng tôi 我们, Các bạn 你们, Họ 他们, hoặc A và B, 这些...).
2. Phủ định hoàn toàn: 都不 + V/Adj (Đều không...).
3. Phủ định một phần: 不都 + V/Adj (Không phải tất cả đều...).`,examples:[{rawZh:"我们都是学生。(Wǒmen dōu shì xuésheng.)",zh:"我们都是学生。",pinyin:"Wǒmen dōu shì xuésheng.",vi:"Chúng tôi đều là học sinh."},{rawZh:"他们都喜欢喝茶。(Tāmen dōu xǐhuan hē chá.)",zh:"他们都喜欢喝茶。",pinyin:"Tāmen dōu xǐhuan hē chá.",vi:"Họ đều thích uống trà."},{rawZh:"这些苹果都很好。(Zhèxiē píngguǒ dōu hěn hǎo.)",zh:"这些苹果都很好。",pinyin:"Zhèxiē píngguǒ dōu hěn hǎo.",vi:"Những quả táo này đều rất ngon."}],tables:null,exercises:null}]},{lessonId:15,lessonKey:"Bài 15",lessonTitleZh:"大兴机场见",lessonTitleFull:"Bài 15: 大兴机场见 (Câu ghép đẳng lập ……，还/也……)",grammarPoints:[{id:"hsk1_b15_g1",num:1,title:"Câu ghép đẳng lập “……，还 / 也……” (Biểu thị sự song hành hoặc bổ sung)",explanation:`Dùng để kết nối hai vế câu có cùng chủ ngữ, diễn tả việc vừa có tính chất/hành động này, lại vừa có thêm tính chất/hành động khác.
- 也 (yě - cũng): Liệt kê các trạng thái hoặc hành động song song, tương đồng nhau.
- 还 (hái - còn/lại còn): Bổ sung thêm tính chất hoặc thông tin mới (thường mang tính nâng cao mức độ).`,formula:"Chủ ngữ + V/Adj 1 + ..., (Chủ ngữ) + 还 / 也 + V/Adj 2",note:"Chủ ngữ ở vế thứ hai có thể lược bỏ nếu giống với vế thứ nhất.",examples:[{rawZh:"他会做饭，也会开车。(Tā huì zuòfàn, yě huì kāichē.)",zh:"他会做饭，也会开车。",pinyin:"Tā huì zuòfàn, yě huì kāichē.",vi:"Anh ấy biết nấu ăn, cũng biết lái xe."},{rawZh:"这件衣服很好看，还很便宜。(Zhè jiàn yīfu hěn hǎokàn, hái hěn piányi.)",zh:"这件衣服很好看，还很便宜。",pinyin:"Zhè jiàn yīfu hěn hǎokàn, hái hěn piányi.",vi:"Bộ quần áo này rất đẹp, lại còn rất rẻ."},{rawZh:"我学习汉语，也学习英文。(Wǒ xuéxí Hànyǔ, yě xuéxí Yīngwén.)",zh:"我学习汉语，也学习英文。",pinyin:"Wǒ xuéxí Hànyǔ, yě xuéxí Yīngwén.",vi:"Tôi học tiếng Hán, cũng học tiếng Anh."}],tables:null,exercises:null}]}];window.HSK1_STRUCTURED_GRAMMAR=n;const h=[{lessonId:1,lessonKey:"Bài 1",lessonTitleZh:"她请我们去了北京烤鸭",lessonTitleFull:"Bài 1: 她请我们去了北京烤鸭",grammarPoints:[{id:"hsk2_b1_g1",num:1,title:"Trợ từ ngữ khí “吧” (Biểu thị sự suy đoán / gợi ý)",explanation:'Đặt ở cuối câu để biểu thị ý đề nghị, gợi ý nhẹ nhàng ("...đi", "...nhé") hoặc suy đoán có phần chắc chắn ("...chứ?", "...phải không?").',formula:"S + V + (O) + 吧",note:'Khác với "吗" (hỏi không biết thông tin), "吧" dùng khi người nói đã có suy đoán và chỉ cần xác nhận lại.',examples:[{rawZh:"我们去旅游吧。 (Chúng ta đi du lịch đi.)",zh:"我们去旅游吧。",pinyin:"Wǒmen qù lǚyóu ba.",vi:"Chúng ta đi du lịch đi."},{rawZh:"我们去吃北京烤鸭吧。 (Chúng ta đi ăn vịt quay Bắc Kinh đi.)",zh:"我们去吃北京烤鸭吧。",pinyin:"Wǒmen qù chī Běijīng kǎoyā ba.",vi:"Chúng ta đi ăn vịt quay Bắc Kinh đi."},{rawZh:"他已经懂了吧？ (Anh ấy đã hiểu rồi chứ?)",zh:"他已经懂了吧？",pinyin:"Tā yǐjīng dǒng le ba?",vi:"Anh ấy đã hiểu rồi chứ?"},{rawZh:"我们去买票吧。 (Chúng ta đi mua vé đi.)",zh:"Chúng ta đi mua vé đi.",pinyin:"Wǒmen qù mǎi piào ba.",vi:"Chúng ta đi mua vé đi."},{rawZh:"我介绍一下吧。 (Để tôi giới thiệu một chút nhé.)",zh:"我介绍一下吧。",pinyin:"Wǒ jièshào yíxià ba.",vi:"Để tôi giới thiệu một chút nhé."}],tables:null,exercises:null},{id:"hsk2_b1_g2",num:2,title:"Cấu trúc nhấn mạnh “是……的”",explanation:"Trong tiếng Trung, khi kể lại một sự việc đã xảy ra trong quá khứ, nếu muốn nhấn mạnh vào thời gian, địa điểm hoặc cách thức/phương tiện thực hiện của hành động đó, ta sử dụng cấu trúc “是……的”.",formula:`Khẳng định: S + (是) + [Thời gian / Địa điểm / Cách thức] + V + 的
Phủ định: S + 不是 + [Thời gian / Địa điểm / Cách thức] + V + 的`,note:`1. Chỉ dùng cho hành động ĐÃ HOÀN THÀNH trong quá khứ, không dùng cho tương lai hay thói quen.
2. Ở thể khẳng định "是" có thể lược bỏ, nhưng "的" ở cuối câu là BẮT BUỘC.`,examples:[{rawZh:"我是昨天去北京旅游的。 (Tôi là hôm qua mới đi du lịch Bắc Kinh - Nhấn mạnh thời gian.)",zh:"我是昨天去北京旅游的。",pinyin:"Wǒ shì zuótiān qù Běijīng lǚyóu de.",vi:"Tôi là hôm qua mới đi du lịch Bắc Kinh."},{rawZh:"我是老师介绍来的。 (Tôi là do thầy giáo giới thiệu đến - Nhấn mạnh cách thức/nguồn gốc.)",zh:"我是老师介绍来的。",pinyin:"Wǒ shì lǎoshī jièshào lái de.",vi:"Tôi là do thầy giáo giới thiệu đến."},{rawZh:"我是昨天去接你的。 (Tôi là hôm qua đi đón bạn.)",zh:"我是昨天去接你的。",pinyin:"Wǒ shì zuótiān qù jiē nǐ de.",vi:"Tôi là hôm qua đi đón bạn."},{rawZh:"我是坐车去旅游的。 (Tôi là đi xe đi du lịch - Nhấn mạnh phương tiện.)",zh:"我是坐车去旅游的。",pinyin:"Wǒ shì zuòchē qù lǚyóu de.",vi:"Tôi là đi xe buýt/ngồi xe đi du lịch."},{rawZh:"我是在学校认识他的。 (Tôi là quen biết anh ấy ở trường học - Nhấn mạnh địa điểm.)",zh:"我是在学校认识他的。",pinyin:"Wǒ shì zài xuéxiào rènshi tā de.",vi:"Tôi là quen biết anh ấy ở trường học."}],tables:null,exercises:null},{id:"hsk2_b1_g3",num:3,title:"Câu kiêm ngữ (请, 让, 叫)",explanation:"Câu kiêm ngữ là loại câu gồm hai cụm động từ, trong đó tân ngữ của động từ thứ nhất (V1) đồng thời đóng vai trò là chủ ngữ của động từ thứ hai (V2). Thường dùng để nhờ vả, yêu cầu, mời mọc ai làm việc gì.",formula:"S1 + V1 (请 / 让 / 叫) + S2 (Kiêm ngữ) + V2 + O2",note:`Sự khác biệt giữa 3 động từ phổ biến:
- 请 (qǐng): Dùng khi lịch sự, mời mọc, nhờ vả trang trọng.
- 让 (ràng): Yêu cầu, bảo hoặc cho phép ai đó làm gì (trung tính).
- 叫 (jiào): Dùng trong giao tiếp hàng ngày, khẩu ngữ thân mật khi bảo/gọi ai làm gì.`,examples:[{rawZh:"老师让我去接你。 (Thầy giáo bảo tôi đi đón bạn.)",zh:"老师让我去接你。",pinyin:"Lǎoshī ràng wǒ qù jiē nǐ.",vi:"Thầy giáo bảo tôi đi đón bạn."},{rawZh:"老师让我帮忙。 (Thầy giáo bảo tôi giúp đỡ.)",zh:"老师让我帮忙。",pinyin:"Lǎoshī ràng wǒ bāngmáng.",vi:"Thầy giáo bảo tôi giúp đỡ."},{rawZh:"他让我介绍一下。 (Anh ấy bảo tôi giới thiệu một chút.)",zh:"他让我介绍一下。",pinyin:"Tā ràng wǒ jièshào yíxià.",vi:"Anh ấy bảo tôi giới thiệu một chút."},{rawZh:"我让他帮我。 (Tôi bảo anh ấy giúp tôi.)",zh:"我让他帮我。",pinyin:"Wǒ ràng tā bāng wǒ.",vi:"Tôi bảo anh ấy giúp tôi."},{rawZh:"他请我们吃北京烤鸭。 (Cô ấy mời chúng tôi ăn vịt quay Bắc Kinh.)",zh:"他请我们吃北京烤鸭。",pinyin:"Tā qǐng wǒmen chī Běijīng kǎoyā.",vi:"Cô ấy mời chúng tôi ăn vịt quay Bắc Kinh."}],tables:null,exercises:null}]},{lessonId:2,lessonKey:"Bài 2",lessonTitleZh:"还是打车去北大吧",lessonTitleFull:"Bài 2: 还是打车去北大吧",grammarPoints:[{id:"hsk2_b2_g1",num:1,title:"Cấu trúc “还是……吧” (Lựa chọn / Lời khuyên tốt nhất)",explanation:'Dùng để đưa ra gợi ý, lựa chọn hoặc lời khuyên sau khi đã cân nhắc các phương án khác, mang nghĩa "Hay là... đi / Làm thế này sẽ tốt hơn".',formula:"S + 还是 + V + (O) + 吧",note:"Trong cấu trúc này, 还是 biểu thị phương án được ưu tiên lựa chọn hơn, thường kết hợp với 吧 ở cuối câu.",examples:[{rawZh:"还是打车去吧。 (Hay là gọi xe taxi đi đi.)",zh:"还是打车去吧。",pinyin:"Háishì dǎchē qù ba.",vi:"Hay là gọi xe taxi đi đi."},{rawZh:"还是坐公交车去吧。 (Hay là đi xe buýt đi.)",zh:"还是坐公交车去吧。",pinyin:"Háishì zuò gōngjiāochē qù ba.",vi:"Hay là đi xe buýt đi."},{rawZh:"太晚了，还是回家吧。 (Muộn quá rồi, hay là về nhà đi.)",zh:"太晚了，还是回家吧。",pinyin:"Tài wǎn le, háishì huíjiā ba.",vi:"Muộn quá rồi, hay là về nhà đi."},{rawZh:"还是去北京大学吧。 (Hay là đi Đại học Bắc Kinh đi.)",zh:"还是去北京大学吧。",pinyin:"Háishì qù Běijīng Dàxué ba.",vi:"Hay là đi Đại học Bắc Kinh đi."},{rawZh:"还是去商场看看吧。 (Hay là đi trung tâm thương mại xem thử đi.)",zh:"还是去商场看看吧。",pinyin:"Háishì qù shāngchǎng kànkan ba.",vi:"Hay là đi trung tâm thương mại xem thử đi."}],tables:null,exercises:null},{id:"hsk2_b2_g2",num:2,title:"Biểu thị số ước lượng với “多”",explanation:"Từ “多” (duō) được dùng sau số từ và lượng từ để biểu thị số lượng xấp xỉ nhiều hơn con số đó (hơn, ngoài). Vị trí của “多” phụ thuộc vào việc con số đó là số tròn chục/trăm/nghìn hay số lẻ.",formula:`1. Với SỐ TRÒN (10, 20, 50, 100, 1000...):
Số từ + 多 + Lượng từ + Danh từ

2. Với SỐ LẺ / KHÔNG TRÒN (1, 3, 5, 8, 23, 35...):
Số từ + Lượng từ + 多 + Danh từ`,note:`Quy tắc vàng:
- Số tròn (10, 20, 100...): "多" đứng TRƯỚC lượng từ (chỉ phần lẻ thêm vào sau hàng chục/trăm).
- Số lẻ (3, 5, 8...): "多" đứng SAU lượng từ (chỉ phần lẻ của đơn vị đo đếm đó).`,examples:[{rawZh:"十多个人 (Shí duō gè rén): Hơn 10 người (10 là số tròn -> 多 trước 个)",zh:"十多个人",pinyin:"shí duō gè rén",vi:"Hơn 10 người"},{rawZh:"五十多本书 (Wǔshí duō běn shū): Hơn 50 quyển sách",zh:"五十多本书",pinyin:"wǔshí duō běn shū",vi:"Hơn 50 quyển sách"},{rawZh:"两百多块 (Liǎng bǎi duō kuài): Hơn 200 tệ",zh:"两百多块",pinyin:"liǎng bǎi duō kuài",vi:"Hơn 200 tệ"},{rawZh:"三个多月 (Sān gè duō yuè): Hơn 3 tháng (3 là số lẻ -> 多 sau 个)",zh:"三个多月",pinyin:"sān gè duō yuè",vi:"Hơn 3 tháng"},{rawZh:"五个人多 (Wǔ gè rén duō): Hơn 5 người",zh:"五个人多",pinyin:"wǔ gè rén duō",vi:"Hơn 5 người"},{rawZh:"八本书多 (Bā běn shū duō): Hơn 8 quyển sách",zh:"八本书多",pinyin:"bā běn shū duō",vi:"Hơn 8 quyển sách"}],tables:null,exercises:null},{id:"hsk2_b2_g3",num:3,title:"Định ngữ là Động từ, Cụm động từ hoặc Cụm chủ - vị",explanation:"Trong tiếng Trung, động từ, cụm động từ hoặc cụm chủ-vị có thể đứng trước trợ từ kết cấu “的” để làm định ngữ bổ nghĩa cho danh từ (trung tâm ngữ) đứng sau.",formula:"[Động từ / Cụm động từ / Cụm Chủ - Vị] + 的 + Danh từ (Trung tâm ngữ)",note:"Khi dịch sang tiếng Việt, ta dịch danh từ trung tâm ngữ trước, sau đó dịch phần định ngữ bổ nghĩa phía sau.",examples:[{rawZh:"我买的衣服 (Quần áo tôi mua)",zh:"我买的衣服",pinyin:"wǒ mǎi de yīfu",vi:"Quần áo mà tôi đã mua"},{rawZh:"我看的电影 (Bộ phim tôi xem)",zh:"我看的电影",pinyin:"wǒ kàn de diànyǐng",vi:"Bộ phim tôi xem"},{rawZh:"老师介绍的朋友 (Người bạn mà thầy giáo giới thiệu)",zh:"老师介绍的朋友",pinyin:"lǎoshī jièshào de péngyou",vi:"Người bạn mà thầy giáo giới thiệu"},{rawZh:"我去旅游的地方 (Nơi tôi đi du lịch)",zh:"我去旅游的地方",pinyin:"wǒ qù lǚyóu de dìfang",vi:"Nơi tôi đi du lịch"},{rawZh:"我在网上看的票 (Vé mà tôi xem trên mạng)",zh:"我在网上看的票",pinyin:"wǒ zài wǎngshang kàn de piào",vi:"Vé mà tôi xem trên mạng"}],tables:null,exercises:null}]},{lessonId:3,lessonKey:"Bài 3",lessonTitleZh:"我想去西安旅游",lessonTitleFull:"Bài 3: 我想去西安旅游",grammarPoints:[{id:"hsk2_b3_g1",num:1,title:"Bổ ngữ kết quả (完, 见, 懂, 好, 到)",explanation:"Bổ ngữ kết quả là từ (thường là động từ hoặc tính từ) đứng ngay sau động từ chính để chỉ kết quả hoặc mục đích của hành động đó đã đạt được hay chưa.",formula:`Khẳng định: S + V + [Bổ ngữ kết quả] + (O)
Phủ định: S + 没(有) + V + [Bổ ngữ kết quả] + (O)
Câu hỏi: S + V + [Bổ ngữ kết quả] + (O) + 没(有) / 吗?`,note:'LƯU Ý QUAN TRỌNG: Thể phủ định của bổ ngữ kết quả bắt buộc phải dùng "没有" (hoặc "没"), tuyệt đối KHÔNG dùng "不".',examples:[{rawZh:"我做完作业了。(Tôi làm xong bài tập rồi.)",zh:"我做完作业了。",pinyin:"Wǒ zuò wán zuòyè le.",vi:"Tôi làm xong bài tập rồi."},{rawZh:"我看完了这本书。(Tôi đã đọc xong quyển sách này rồi.)",zh:"我看完了这本书。",pinyin:"Wǒ kàn wán le zhè běn shū.",vi:"Tôi đã đọc xong quyển sách này rồi."},{rawZh:"老师说完了。(Thầy giáo nói xong rồi.)",zh:"老师说完了。",pinyin:"Lǎoshī shuō wán le.",vi:"Thầy giáo nói xong rồi."},{rawZh:"我看见他了。(Tôi nhìn thấy anh ấy rồi.)",zh:"我看见他了。",pinyin:"Wǒ kànjiàn tā le.",vi:"Tôi nhìn thấy anh ấy rồi."},{rawZh:"我听懂老师的话了。(Tôi nghe hiểu lời thầy giáo rồi.)",zh:"我听懂老师的话了。",pinyin:"Wǒ tīng dǒng lǎoshī de huà le.",vi:"Tôi nghe hiểu lời thầy giáo rồi."},{rawZh:"我买到票了。(Tôi đã mua được vé rồi.)",zh:"我买到票了。",pinyin:"Wǒ mǎi dào piào le.",vi:"Tôi đã mua được vé rồi."}],tables:[{title:"Bảng Các Bổ Ngữ Kết Quả Thông Dụng Nhất HSK 2",headers:["Bổ ngữ","Ý nghĩa","Ví dụ ghép","Dịch nghĩa"],rows:[["完 (wán)","Làm xong / Hết sạch","做完 (zuò wán)","Làm xong bài tập, công việc"],["见 (jiàn)","Nhìn thấy / Nghe thấy","看见 (kànjiàn), 听见 (tīngjiàn)","Nhìn thấy người, nghe thấy tiếng"],["懂 (dǒng)","Hiểu rõ qua hành động","听懂 (tīng dǒng), 看懂 (kàn dǒng)","Nghe hiểu bài giảng, đọc hiểu sách"],["好 (hǎo)","Xong xuôi & Đạt trạng thái tốt/sẵn sàng","做好 (zuò hǎo), 买好 (mǎi hǎo)","Nấu xong cơm ngon, chuẩn bị xong"],["到 (dào)","Đạt được mục đích / Đến nơi","买到 (mǎi dào), 找到 (zhǎo dào)","Mua được vé, tìm thấy đồ vật"]]}],exercises:null},{id:"hsk2_b3_g2",num:2,title:"Hình thức lặp lại của Động từ (AA, A一A, AB-AB, AAB)",explanation:"Lặp lại động từ trong tiếng Trung nhằm: làm nhẹ ngữ khí câu (lời khuyên/nhờ vả thân mật), diễn tả hành động làm thử, hoặc hành động diễn ra trong thời gian ngắn/nhanh chóng.",formula:`1. Đơn âm tiết: AA hoặc A一A (Khẳng định/hiện tại) | A了A (Quá khứ)
2. Song âm tiết: AB-AB (Không chèn 一)
3. Từ ly hợp (V+O): AAB hoặc A了A + B`,note:`Quy tắc lặp lại chuẩn:
- Đơn âm tiết: 看看 (kànkan), 听一听 (tīng yi tīng), 试了试 (shì le shì).
- Song âm tiết: 休息休息 (xiūxi xiūxi), 介绍介绍 (jièshào jièshào) - KHÔNG nói 休息一休息.
- Từ ly hợp: 睡觉 -> 睡睡觉 (shuì shuì jiào), 散步 -> 散散步 (sàn sàn bù), 洗澡 -> 洗洗澡 (xǐ xǐ zǎo).`,examples:[{rawZh:"你看看这件衣服。(Bạn xem thử bộ quần áo này đi.)",zh:"你看看这件衣服。",pinyin:"Nǐ kànkan zhè jiàn yīfu.",vi:"Bạn xem thử bộ quần áo này đi."},{rawZh:"我听了一听这首歌。(Tôi đã nghe thử bài hát này.)",zh:"我听了一听这首歌。",pinyin:"Wǒ tīng le yì tīng zhè shǒu gē.",vi:"Tôi đã nghe thử bài hát này."},{rawZh:"周末我们在家休息休息吧。(Cuối tuần chúng ta ở nhà nghỉ ngơi một chút nhé.)",zh:"周末我们在家休息休息吧。",pinyin:"Zhōumò wǒmen zài jiā xiūxi xiūxi ba.",vi:"Cuối tuần chúng ta ở nhà nghỉ ngơi một chút nhé."},{rawZh:"吃完饭我们去散散步。(Ăn cơm xong chúng ta đi dạo một chút nhé.)",zh:"吃完饭我们去散散步。",pinyin:"Chī wán fàn wǒmen qù sàn sàn bù.",vi:"Ăn cơm xong chúng ta đi dạo một chút nhé."},{rawZh:"我睡了睡午觉。(Tôi đã chợp mắt ngủ trưa một lúc.)",zh:"我睡了睡午觉。",pinyin:"Wǒ shuì le shuì wǔjiào.",vi:"Tôi đã chợp mắt ngủ trưa một lúc."}],tables:null,exercises:null}]},{lessonId:4,lessonKey:"Bài 4",lessonTitleZh:"你穿红色的很好看",lessonTitleFull:"Bài 4: 你穿红色的很好看",grammarPoints:[{id:"hsk2_b4_g1",num:1,title:"Trợ từ động thái “过” (Biểu thị trải nghiệm đã từng qua)",explanation:"Trợ từ “过” (guo) đặt ngay sau động từ để diễn tả một hành động hoặc trải nghiệm đã từng xảy ra trong quá khứ và hiện tại không còn tiếp diễn nữa.",formula:`Khẳng định: S + V + 过 + (O)
Phủ định: S + 没(有) + V + 过 + (O)
Nghi vấn: S + V + 过 + (O) + 没有 / 吗?`,note:'Phủ định bắt buộc dùng "没(有)" + V + 过, tuyệt đối không dùng "不".',examples:[{rawZh:"我去过北京。(Tôi đã từng đi Bắc Kinh.)",zh:"我去过北京。",pinyin:"Wǒ qù guo Běijīng.",vi:"Tôi đã từng đi Bắc Kinh."},{rawZh:"我没吃过北京烤鸭。(Tôi chưa từng ăn vịt quay Bắc Kinh.)",zh:"我没吃过北京烤鸭。",pinyin:"Wǒ méi chī guo Běijīng kǎoyā.",vi:"Tôi chưa từng ăn vịt quay Bắc Kinh."},{rawZh:"你看过这个电影吗？(Bạn đã từng xem bộ phim này chưa?)",zh:"你看过这个电影吗？",pinyin:"Nǐ kàn guo zhè gè diànyǐng ma?",vi:"Bạn đã từng xem bộ phim này chưa?"}],tables:null,exercises:null},{id:"hsk2_b4_g2",num:2,title:"Câu ghép quan hệ nhân quả “因为……，所以……”",explanation:"Liên từ “因为” (yīnwèi - vì, bởi vì) biểu thị nguyên nhân, “所以” (suǒyǐ - cho nên, vì vậy) biểu thị kết quả sinh ra từ nguyên nhân đó.",formula:"因为 + [Nguyên nhân], 所以 + [Kết quả]",note:'Trong khẩu ngữ có thể chỉ dùng một trong hai từ "因为" hoặc "所以" mà người nghe vẫn hiểu trọn vẹn ý.',examples:[{rawZh:"因为下雨，所以我没去。(Vì trời mưa, nên tôi không đi.)",zh:"因为下雨，所以我没去。",pinyin:"Yīnwèi xià yǔ, suǒyǐ wǒ méi qù.",vi:"Vì trời mưa, nên tôi không đi."},{rawZh:"因为我很累，所以想休息。(Vì tôi rất mệt, nên muốn nghỉ ngơi.)",zh:"因为我很累，所以想休息。",pinyin:"Yīnwèi wǒ hěn lèi, suǒyǐ xiǎng xiūxi.",vi:"Vì tôi rất mệt, nên muốn nghỉ ngơi."},{rawZh:"因为他是老师，所以他懂。(Vì ông ấy là giáo viên, nên ông ấy hiểu.)",zh:"因为他是老师，所以他懂。",pinyin:"Yīnwèi tā shì lǎoshī, suǒyǐ tā dǒng.",vi:"Vì ông ấy là giáo viên, nên ông ấy hiểu."},{rawZh:"因为衣服很贵，所以我没买。(Vì quần áo rất đắt, nên tôi không mua.)",zh:"因为衣服很贵，所以我没买。",pinyin:"Yīnwèi yīfu hěn guì, suǒyǐ wǒ méi mǎi.",vi:"Vì quần áo rất đắt, nên tôi không mua."},{rawZh:"因为天气很热，所以我不出门。(Vì thời tiết rất nóng, nên tôi không ra ngoài.)",zh:"因为天气很热，所以我不出门。",pinyin:"Yīnwèi tiānqì hěn rè, suǒyǐ wǒ bù chūmén.",vi:"Vì thời tiết rất nóng, nên tôi không ra ngoài."}],tables:null,exercises:null},{id:"hsk2_b4_g3",num:3,title:"Cụm từ chữ “的” (Lược bỏ trung tâm ngữ)",explanation:"Khi ngữ cảnh đã rõ ràng (cả người nói và người nghe đều biết đang nhắc đến đối tượng/đồ vật nào), ta có thể lược bỏ danh từ trung tâm ngữ phía sau “的” để câu nói ngắn gọn và tự nhiên hơn.",formula:"[Định ngữ: Đại từ sở hữu / Tính từ màu sắc, kích thước, đặc điểm] + 的",note:`1. Chỉ sở hữu: 我的 (của tôi), 他的 (của anh ấy).
2. Chỉ màu sắc/kích thước: 红色的 (cái màu đỏ), 大的 (cái to), 新的 (cái mới).`,examples:[{rawZh:"这本书是我的。(Quyển sách này là của tôi - Rút gọn từ: 我的书)",zh:"这本书是我的。",pinyin:"Zhè běn shū shì wǒ de.",vi:"Quyển sách này là của tôi."},{rawZh:"那部手机是我朋友的。(Chiếc điện thoại đó là của bạn tôi.)",zh:"那部手机是我朋友的。",pinyin:"Nà bù shǒujī shì wǒ péngyou de.",vi:"Chiếc điện thoại đó là của bạn tôi."},{rawZh:"我想要红色的。(Tôi muốn cái màu đỏ - Rút gọn từ: 红色的衣服)",zh:"我想要红色的。",pinyin:"Wǒ xiǎng yào hóngsè de.",vi:"Tôi muốn cái màu đỏ."},{rawZh:"我想买大的，不想买小的。(Tôi muốn mua cái to, không muốn mua cái nhỏ.)",zh:"我想买大的，不想买小的。",pinyin:"Wǒ xiǎng mǎi dà de, bù xiǎng mǎi xiǎo de.",vi:"Tôi muốn mua cái to, không muốn mua cái nhỏ."},{rawZh:"这个手机是新的，那个是旧的。(Chiếc điện thoại này là cái mới, chiếc kia là cái cũ.)",zh:"这个手机是新的，那个是旧的。",pinyin:"Zhè gè shǒujī shì xīn de, nà ge shì jiù de.",vi:"Chiếc điện thoại này là cái mới, chiếc kia là cái cũ."}],tables:null,exercises:null}]},{lessonId:5,lessonKey:"Bài 5",lessonTitleZh:"第一次去中国朋友家",lessonTitleFull:"Bài 5: 第一次去中国朋友家",grammarPoints:[{id:"hsk2_b5_g1",num:1,title:"Bổ ngữ xu hướng đơn (来 / 去)",explanation:"Bổ ngữ xu hướng đơn đứng sau động từ để miêu tả hướng di chuyển của hành động lấy vị trí của người nói làm mốc chuẩn: hướng về phía người nói (dùng 来) hoặc rời xa người nói (dùng 去).",formula:`1. Không có tân ngữ: Động từ + 来 / 去
2. Tân ngữ là ĐỊA ĐIỂM: Động từ + Địa điểm + 来 / 去
3. Tân ngữ là ĐỒ VẬT: Động từ + (来/去) + Tân ngữ (hoặc: Động từ + Tân ngữ + 来/去)`,note:`Quy tắc mốc chuẩn:
- 来 (lái): Hành động tiến về phía người nói ("vào đây", "lên đây", "đến đây").
- 去 (qù): Hành động đi ra xa người nói ("vào đó", "lên đó", "đi kia").`,examples:[{rawZh:"请进来。(Mời vào đây - Người nói đang ở trong phòng).",zh:"请进来。",pinyin:"Qǐng jìnlái.",vi:"Mời vào đây."},{rawZh:"他上楼来了。(Anh ấy lên lầu đây rồi - Người nói đang ở trên lầu).",zh:"他上楼来了。",pinyin:"Tā shànglóu lái le.",vi:"Anh ấy lên lầu đây rồi."},{rawZh:"他回家去了。(Anh ấy về nhà rồi - Người nói không ở nhà anh ấy).",zh:"他回家去了。",pinyin:"Tā huíjiā qù le.",vi:"Anh ấy về nhà rồi."},{rawZh:"他们进去了。(Họ vào trong đó rồi - Người nói đang ở ngoài).",zh:"他们进去了。",pinyin:"Tāmen jìnqu le.",vi:"Họ vào trong đó rồi."},{rawZh:"你帮我拿来吧。(Bạn giúp tôi mang tới đây nhé).",zh:"你帮我拿来吧。",pinyin:"Nǐ bāng wǒ ná lái ba.",vi:"Bạn giúp tôi mang tới đây nhé."}],tables:[{title:"Bảng Phối Hợp Động Từ Di Chuyển Với Bổ Ngữ Xu Hướng 来 / 去",headers:["Động từ gốc","+ 来 (Hướng về phía người nói)","+ 去 (Ra xa phía người nói)"],rows:[["进 (jìn - vào)","进来 (jìnlái - Vào đây)","进去 (jìnqu - Vào đó)"],["出 (chū - ra)","出来 (chūlái - Ra đây)","出去 (chūqu - Ra đó)"],["上 (shàng - lên)","上来 (shànglái - Lên đây)","上去 (shàngqu - Lên đó)"],["下 (xià - xuống)","下来 (xiàlái - Xuống đây)","下去 (xiàqu - Xuống đó)"],["回 (huí - về)","回来 (huílái - Về đây)","回去 (huíqu - Về đó)"],["过 (guò - qua)","过来 (guòlái - Qua đây)","过去 (guòqu - Qua đó)"]]},{title:"Bảng Động Từ Hành Động Kết Hợp Mang/Cầm Đi & Mang/Cầm Đến",headers:["Động từ","Ý nghĩa","+ 来 (Mang về phía tôi)","+ 去 (Mang ra xa tôi)"],rows:[["拿 (ná)","Cầm, lấy","拿来 (ná lái - Mang tới đây)","拿去 (ná qù - Mang đi chỗ khác)"],["送 (sòng)","Tặng, đưa","送来 (sòng lái - Mang đến/tặng đến)","送去 (sòng qù - Đưa đi/gửi đi)"],["买 (mǎi)","Mua","买来 (mǎi lái - Mua mang về)","买去 (mǎi qù - Mua mang đi)"],["开 (kāi)","Lái (xe)","开来 (kāi lái - Lái tới đây)","开去 (kāi qù - Lái đi chỗ khác)"],["跑 (pǎo)","Chạy","跑来 (pǎo lái - Chạy tới đây)","跑去 (pǎo qù - Chạy đi chỗ khác)"]]}],exercises:null},{id:"hsk2_b5_g2",num:2,title:"Cấu trúc cố định “都……了” (Nhấn mạnh mức độ / thời gian)",explanation:'Cấu trúc “都……了” dùng để nhấn mạnh sự việc hoặc thời gian đã đạt đến một mức độ cao hoặc trạng thái muộn, thường mang sắc thái giục giã, nhắc nhở hoặc phàn nàn ("Đã... rồi mà...").',formula:"都 + [Thời gian / Số lượng / Động từ / Tính từ] + 了",note:'Khác với "已经", "都" mang ngữ khí cảm thán và nhấn mạnh cảm xúc của người nói nhiều hơn.',examples:[{rawZh:"都八点了，你还不起床吗？ (Đã 8 giờ rồi, bạn vẫn chưa dậy à?)",zh:"都八点了，你还不起床吗？",pinyin:"Dōu bā diǎn le, nǐ hái bù qǐchuáng ma?",vi:"Đã 8 giờ rồi, bạn vẫn chưa dậy à?"},{rawZh:"我都去过北京了，不想再去了。 (Tôi đã từng đi Bắc Kinh rồi, không muốn đi nữa đâu.)",zh:"我都去过北京了，不想再去了。",pinyin:"Wǒ dōu qù guo Běijīng le, bù xiǎng zài qù le.",vi:"Tôi đã từng đi Bắc Kinh rồi, không muốn đi nữa đâu."}],tables:null,exercises:null}]},{lessonId:6,lessonKey:"Bài 6",lessonTitleZh:"小雪，生日快乐！",lessonTitleFull:"Bài 6: 小雪，生日快乐！",grammarPoints:[{id:"hsk2_b6_g1",num:1,title:"Hình thức lặp lại của Tính từ (AA, AABB)",explanation:"Lặp lại tính từ dùng để tăng cường mức độ miêu tả, làm cho câu văn sinh động, tạo cảm giác thân mật, đáng yêu hoặc nhấn mạnh vẻ đẹp, hình dáng, màu sắc.",formula:`1. Đơn âm tiết: AA (thường thêm 的: AA的)
2. Song âm tiết: AABB (AABB的)`,note:`1. Thường thêm "的" phía sau khi làm vị ngữ hoặc định ngữ.
2. Phía trước tính từ lặp lại KHÔNG dùng các phó từ chỉ mức độ như 很, 非常, 太.
3. Không dùng trong câu phủ định.`,examples:[{rawZh:"他的眼睛大大的，看起来非常漂亮。 (Đôi mắt của cô ấy to tròn, trông vô cùng xinh đẹp.)",zh:"他的眼睛大大的，看起来非常漂亮。",pinyin:"Tā de yǎnjing dàdà de, kàn qǐlái fēicháng piàoliang.",vi:"Đôi mắt của cô ấy to tròn, trông vô cùng xinh đẹp."},{rawZh:"那家商场里的衣服都漂漂亮亮的。 (Quần áo trong trung tâm thương mại đó đều đẹp đẽ, xinh xắn.)",zh:"那家商场里的衣服都漂漂亮亮的。",pinyin:"Nà jiā shāngchǎng lǐ de yīfu dōu piàopiaoliangliang de.",vi:"Quần áo trong trung tâm thương mại đó đều đẹp đẽ, xinh xắn."}],tables:null,exercises:null},{id:"hsk2_b6_g2",num:2,title:"Cụm từ cố định “什么的” (Vân vân, v.v.)",explanation:'Cụm từ “什么的” (shénme de) đứng ở cuối phần liệt kê để thay thế cho "vân vân", "v.v." hoặc "những thứ tương tự như thế" trong khẩu ngữ giao tiếp hàng ngày.',formula:"[Danh từ A], [Danh từ B] + 什么的",note:"Chỉ dùng trong khẩu ngữ thân mật, giúp câu nói ngắn gọn mà không cần liệt kê hết toàn bộ các món đồ.",examples:[{rawZh:"我买衣服、裤子什么的。 (Tôi mua quần áo, quần dài vân vân.)",zh:"我买衣服、裤子什么的。",pinyin:"Wǒ mǎi yīfu, kùzi shénme de.",vi:"Tôi mua quần áo, quần dài vân vân."},{rawZh:"我们要喝茶、奶茶什么的。 (Chúng tôi muốn uống trà, trà sữa vân vân.)",zh:"我们要喝茶、奶茶什么的。",pinyin:"Wǒmen yào hē chá, nǎichá shénme de.",vi:"Chúng tôi muốn uống trà, trà sữa vân vân."},{rawZh:"周末我常常看电影、看书什么的。 (Cuối tuần tôi thường xem phim, đọc sách vân vân.)",zh:"周末我常常看电影、看书什么的。",pinyin:"Zhōumò wǒ chángcháng kàn diànyǐng, kànshū shénme de.",vi:"Cuối tuần tôi thường xem phim, đọc sách vân vân."},{rawZh:"桌子上有电脑、杯子、书、笔什么的。 (Trên bàn có máy tính, cốc, sách, bút vân vân.)",zh:"桌子上有电脑、杯子、书、笔什么的。",pinyin:"Zhuōzi shàng yǒu diànnǎo, bēizi, shū, bǐ shénme de.",vi:"Trên bàn có máy tính, cốc, sách, bút vân vân."},{rawZh:"你拿来一些水、面包和苹果什么的。 (Bạn mang đến một ít nước, bánh mì và táo vân vân.)",zh:"你拿来一些水、面包和苹果什么的。",pinyin:"Nǐ ná lái yìxiē shuǐ, miànbāo hé píngguǒ shénme de.",vi:"Bạn mang đến một ít nước, bánh mì và táo vân vân."}],tables:null,exercises:null},{id:"hsk2_b6_g3",num:3,title:"Trợ từ kết cấu “地” (Nối trạng ngữ với động từ)",explanation:"Trợ từ “地” (de) dùng để nối thành phần trạng ngữ (thường là tính từ hoặc cụm tính từ miêu tả cách thức/tâm trạng) với động từ đứng sau, biểu thị hành động diễn ra như thế nào.",formula:"[Tính từ / Trạng từ / Cụm từ miêu tả cách thức] + 地 + Động từ",note:`MẸO PHÂN BIỆT 3 CHỮ "DE" QUAN TRỌNG NHẤT TIẾNG TRUNG:
- 的 (de): Đứng trước DANH TỪ (Định ngữ + 的 + Danh từ, ví dụ: 我的书).
- 得 (de): Đứng sau ĐỘNG TỪ chỉ mức độ/kết quả (Động từ + 得 + Tính từ, ví dụ: 说得很好).
- 地 (de): Đứng trước ĐỘNG TỪ chỉ cách thức hành động (Tính từ + 地 + Động từ, ví dụ: 高兴地学).`,examples:[{rawZh:"高高兴兴地去玩。 (Vui vẻ đi chơi.)",zh:"高高兴兴地去玩。",pinyin:"Gāogāoxìngxìng de qù wán.",vi:"Vui vẻ đi chơi."},{rawZh:"快快地走。 (Đi thật nhanh.)",zh:"快快地走。",pinyin:"Kuàikuài de zǒu.",vi:"Đi thật nhanh."},{rawZh:"好好地学习。 (Học tập thật tốt.)",zh:"好好地学习。",pinyin:"Hǎohāo de xuéxí.",vi:"Học tập thật tốt."},{rawZh:"慢慢地看书。 (Từ từ đọc sách.)",zh:"慢慢地看书。",pinyin:"Mànmàn de kànshū.",vi:"Từ từ đọc sách."}],tables:null,exercises:null}]},{lessonId:7,lessonKey:"Bài 7",lessonTitleZh:"他篮球打得很好",lessonTitleFull:"Bài 7: 他篮球打得很好",grammarPoints:[{id:"hsk2_b7_g1",num:1,title:"Câu ghép rút gọn “一……就……” (Vừa... liền...)",explanation:'Dùng để diễn tả hai hành động xảy ra liên tiếp nhau (hành động 2 diễn ra ngay lập tức sau hành động 1), hoặc hành động 1 là điều kiện/nguyên nhân dẫn đến kết quả ở hành động 2 ("Vừa... liền...", "Ngay khi... thì...").',formula:`Chủ ngữ + 一 + Hành động 1 + 就 + Hành động 2
(Nếu 2 chủ ngữ khác nhau: S1 + 一 + V1, S2 + 就 + V2)`,note:"Khi có 2 chủ ngữ khác nhau, S1 đứng trước 一, S2 đứng trước 就.",examples:[{rawZh:"我一回家就吃饭。 (Tôi vừa về đến nhà là ăn cơm ngay.)",zh:"我一回家就吃饭。",pinyin:"Wǒ yì huíjiā jiù chīfàn.",vi:"Tôi vừa về đến nhà là ăn cơm ngay."},{rawZh:"他一来就问我。 (Anh ấy vừa đến là hỏi tôi ngay.)",zh:"他一来就问我。",pinyin:"Tā yì lái jiù wèn wǒ.",vi:"Anh ấy vừa đến là hỏi tôi ngay."},{rawZh:"天一下雨，我就不出门。 (Trời vừa mưa là tôi liền không ra ngoài.)",zh:"天一下雨，我就不出门。",pinyin:"Tiān yí xià yǔ, wǒ jiù bù chūmén.",vi:"Trời vừa mưa là tôi liền không ra ngoài."},{rawZh:"你一看见老师，就告诉他。 (Bạn vừa nhìn thấy thầy giáo thì báo cho thầy ngay nhé.)",zh:"你一看见老师，就告诉他。",pinyin:"Nǐ yí kànjiàn lǎoshī, jiù gàosu tā.",vi:"Bạn vừa nhìn thấy thầy giáo thì báo cho thầy ngay nhé."},{rawZh:"一到星期六，阴天中就跟同学去打篮球。 (Cứ đến thứ Bảy là Âm Thiên Trung lại cùng bạn học đi đánh bóng rổ.)",zh:"一到星期六，阴天中就跟同学去打篮球。",pinyin:"Yí dào xīngqīliù, Yīn Tiānzhōng jiù gēn tóngxué qù dǎ lánqiú.",vi:"Cứ đến thứ Bảy là Âm Thiên Trung lại cùng bạn học đi đánh bóng rổ."}],tables:null,exercises:null},{id:"hsk2_b7_g2",num:2,title:"Bổ ngữ trạng thái / Bổ ngữ mức độ với “得”",explanation:"Bổ ngữ trạng thái đứng sau động từ (kết nối bởi “得”) để đánh giá, nhận xét hành động được thực hiện như thế nào (tốt/xấu, nhanh/chậm, cao/thấp).",formula:`Khẳng định: V + 得 + Tính từ
Phủ định: V + 得 + 不 + Tính từ
Nghi vấn: V + 得 + Tính từ + 吗? (hoặc: V + 得 + Adj + 不 + Adj? / V + 得 + 怎么样?)`,note:`QUY TẮC LẶP LẠI ĐỘNG TỪ KHI CÓ TÂN NGỮ (O):
Khi câu có tân ngữ, bắt buộc phải lặp lại động từ trước "得":
S + V + O + V + 得 + Tính từ (hoặc: S + O + V + 得 + Tính từ)
Ví dụ:
- Sai: 他说汉语得很好。
- Đúng: 他说汉语说得很好。 (Anh ấy nói tiếng Trung nói rất tốt).`,examples:[{rawZh:"他跑得还可以。 (Anh ấy chạy cũng được.)",zh:"他跑得还可以。",pinyin:"Tā pǎo de hái kěyǐ.",vi:"Anh ấy chạy cũng được."},{rawZh:"他们玩得很高兴。 (Họ chơi rất vui vẻ.)",zh:"他们玩得很高兴。",pinyin:"Tāmen wán de hěn gāoxìng.",vi:"Họ chơi rất vui vẻ."},{rawZh:"我游泳游得不快。 (Tôi bơi không nhanh - Lặp lại động từ 游).",zh:"我游泳游得不快。",pinyin:"Wǒ yóuyǒng yóu de bú kuài.",vi:"Tôi bơi không nhanh."},{rawZh:"你篮球打得怎么样？ (Bạn chơi bóng rổ như thế nào?)",zh:"你篮球打得怎么样？",pinyin:"Nǐ lánqiú dǎ de zěnmeyàng?",vi:"Bạn chơi bóng rổ như thế nào?"},{rawZh:"白天月写汉字写得很好看。 (Bạch Thiên Nguyệt viết chữ Hán viết rất đẹp.)",zh:"白天月写汉字写得很好看。",pinyin:"Bái Tiānyuè xiě hànzì xiě de hěn hǎokàn.",vi:"Bạch Thiên Nguyệt viết chữ Hán viết rất đẹp."}],tables:null,exercises:null}]},{lessonId:8,lessonKey:"Bài 8",lessonTitleZh:"虽然你忘了，但是我记得",lessonTitleFull:"Bài 8: 虽然你忘了，但是我记得",grammarPoints:[{id:"hsk2_b8_g1",num:1,title:"Câu so sánh cơ bản với “比” (1)",explanation:"Dùng để so sánh tính chất, đặc điểm giữa hai người hoặc hai sự vật (A hơn B về mặt nào đó).",formula:`A + 比 + B + Tính từ
(Nhấn mạnh hơn: A + 比 + B + 还 / 更 + Tính từ)`,note:`LƯU Ý CỰC KỲ QUAN TRỌNG:
Tuyệt đối KHÔNG dùng các phó từ chỉ mức độ (như 很, 非常, 真, 太) trước tính từ trong câu chữ 比. (Sai: 他比我很高 -> Đúng: 他比我高).
Nếu muốn nhấn mạnh mức độ cao hơn, ta dùng "更" (càng) hoặc "还" (vẫn/còn).`,examples:[{rawZh:"他比我高。 (Anh ấy cao hơn tôi.)",zh:"他比我高。",pinyin:"Tā bǐ wǒ gāo.",vi:"Anh ấy cao hơn tôi."},{rawZh:"今天比昨天还热。 (Hôm nay còn nóng hơn cả hôm qua.)",zh:"今天比昨天还热。",pinyin:"Jīntiān bǐ zuótiān hái rè.",vi:"Hôm qua còn nóng hơn hôm nay."},{rawZh:"这个手机比那个手机更便宜。 (Điện thoại này càng rẻ hơn điện thoại kia.)",zh:"这个手机比那个手机更便宜。",pinyin:"Zhè gè shǒujī bǐ nà ge shǒujī gèng piányi.",vi:"Điện thoại này rẻ hơn điện thoại kia."},{rawZh:"这本书比那本书更好看。 (Quyển sách này hay hơn quyển sách kia.)",zh:"这本书比那本书更好看。",pinyin:"Zhè běn shū bǐ nà běn shū gèng hǎokàn.",vi:"Quyển sách này hay hơn quyển sách kia."}],tables:null,exercises:null},{id:"hsk2_b8_g2",num:2,title:"Câu ghép chuyển ý “虽然……，但是……” (Tuy... nhưng...)",explanation:'Biểu thị quan hệ nhượng bộ và chuyển tiếp ý, diễn tả sự đối lập, tương phản giữa hai vế câu ("Mặc dù / Tuy rằng... nhưng mà...").',formula:"虽然 + [Vế 1 (Nhượng bộ)], (但是 / 可是) + [Vế 2 (Chuyển ý)]",note:'Trong giao tiếp linh hoạt, có thể dùng cả cặp "虽然...但是..." hoặc lược bỏ một trong hai từ.',examples:[{rawZh:"虽然今天下雨，但是我们想去商场。 (Mặc dù hôm nay trời mưa, nhưng chúng tôi vẫn muốn đi trung tâm thương mại.)",zh:"虽然今天下雨，但是我们想去商场。",pinyin:"Suīrán jīntiān xià yǔ, dànshì wǒmen xiǎng qù shāngchǎng.",vi:"Mặc dù hôm nay trời mưa, nhưng chúng tôi vẫn muốn đi trung tâm thương mại."},{rawZh:"虽然这件衣服很贵，可是很好看。 (Mặc dù chiếc áo này đắt, nhưng rất đẹp.)",zh:"虽然这件衣服很贵，可是很好看。",pinyin:"Suīrán zhè jiàn yīfu hěn guì, kěshì hěn hǎokàn.",vi:"Mặc dù chiếc áo này đắt, nhưng rất đẹp."},{rawZh:"虽然他很累，但他还是想去学习。 (Mặc dù anh ấy rất mệt, nhưng anh ấy vẫn muốn đi học.)",zh:"虽然他很累，但他还是想去学习。",pinyin:"Suīrán tā hěn lèi, dàn tā háishì xiǎng qù xuéxí.",vi:"Mặc dù anh ấy rất mệt, nhưng anh ấy vẫn muốn đi học."},{rawZh:"虽然学中文很难，但是很有意思。 (Mặc dù học tiếng Trung rất khó, nhưng rất thú vị.)",zh:"虽然学中文很难，但是很有意思。",pinyin:"Suīrán xué Zhōngwén hěn nán, dànshì hěn yǒu yìsi.",vi:"Mặc dù học tiếng Trung rất khó, nhưng rất thú vị."},{rawZh:"虽然他没有车，但是他常常去旅游。 (Mặc dù anh ấy không có xe, nhưng anh ấy thường xuyên đi du lịch.)",zh:"虽然他没有车，但是他常常去旅游。",pinyin:"Suīrán tā méiyǒu chē, dànshì tā chángcháng qù lǚyóu.",vi:"Mặc dù anh ấy không có xe, nhưng anh ấy thường xuyên đi du lịch."}],tables:null,exercises:null}]},{lessonId:9,lessonKey:"Bài 9",lessonTitleZh:"我去买杯奶茶",lessonTitleFull:"Bài 9: 我去买杯奶茶",grammarPoints:[{id:"hsk2_b9_g1",num:1,title:"Câu so sánh không bằng với “没有” (2)",explanation:'Dùng để so sánh sự vật A không đạt đến mức độ của sự vật B ("A không [tính từ] bằng B").',formula:`Khẳng định: A + 没有 + B + (这么 / 那么) + Tính từ
Nghi vấn: A + 有没有 + B + (这么/那么) + Tính từ? (hoặc: A + 有 + B + 那么 + Tính từ + 吗?)`,note:'Có thể thêm "这么" (mức này) hoặc "那么" (mức kia) trước tính từ để nhấn mạnh mức độ so sánh.',examples:[{rawZh:"我没有你高。 (Tôi không cao bằng bạn.)",zh:"我没有你高。",pinyin:"Wǒ méiyǒu nǐ gāo.",vi:"Tôi không cao bằng bạn."},{rawZh:"他的书没有我的书那么多。 (Sách của anh ấy không nhiều bằng sách của tôi.)",zh:"他的书没有我的书那么多。",pinyin:"Tā de shū méiyǒu wǒ de shū nàme duō.",vi:"Sách của anh ấy không nhiều bằng sách của tôi."},{rawZh:"这儿的苹果没有那儿的那么便宜。 (Táo ở đây không rẻ bằng táo ở đằng kia.)",zh:"这儿的苹果没有那儿的那么便宜。",pinyin:"Zhèr de píngguǒ méiyǒu nàr de nàme piányi.",vi:"Táo ở đây không rẻ bằng táo ở đằng kia."},{rawZh:"他没有我想的那么忙。 (Anh ấy không bận như tôi nghĩ.)",zh:"他没有我想的那么忙。",pinyin:"Tā méiyǒu wǒ xiǎng de nàme máng.",vi:"Anh ấy không bận như tôi nghĩ."},{rawZh:"你有他那么高吗？ (Bạn có cao bằng anh ấy không?)",zh:"你有他那么高吗？",pinyin:"Nǐ yǒu tā nàme gāo ma?",vi:"Bạn có cao bằng anh ấy không?"}],tables:null,exercises:null},{id:"hsk2_b9_g2",num:2,title:"Giới từ “离” (Khoảng cách không gian & Thời gian)",explanation:"Giới từ “离” (lí - cách) dùng để diễn tả khoảng cách địa lý giữa hai địa điểm hoặc khoảng cách thời gian từ hiện tại tới một mốc sự kiện trong tương lai.",formula:`1. Khoảng cách địa điểm: A + 离 + B + (很) + [远 / 近 / Số đo km]
2. Khoảng cách thời gian: 离 + [Mốc sự kiện] + 还有 + [Khoảng thời gian]`,note:null,examples:[{rawZh:"我家离学校很远。 (Nhà tôi cách trường rất xa.)",zh:"我家离学校很远。",pinyin:"Wǒ jiā lí xuéxiào hěn yuǎn.",vi:"Nhà tôi cách trường rất xa."},{rawZh:"这儿离火车站五公里。 (Chỗ này cách ga tàu 5 cây số.)",zh:"这儿离火车站五公里。",pinyin:"Zhèr lí huǒchēzhàn wǔ gōnglǐ.",vi:"Chỗ này cách ga tàu 5 cây số."},{rawZh:"学校离车站不远。 (Trường học cách trạm xe không xa.)",zh:"学校离车站不远。",pinyin:"Xuéxiào lí chēzhàn bù yuǎn.",vi:"Trường học cách trạm xe không xa."},{rawZh:"离春节还有三天。 (Còn 3 ngày nữa là đến Tết.)",zh:"离春节还有三天。",pinyin:"Lí Chūnjié hái yǒu sān tiān.",vi:"Còn 3 ngày nữa là đến Tết."},{rawZh:"离考试还有两个小时。 (Còn 2 tiếng nữa là đến giờ thi.)",zh:"离考试还有两个小时。",pinyin:"Lí kǎoshì hái yǒu liǎng gè xiǎoshí.",vi:"Còn 2 tiếng nữa là đến giờ thi."},{rawZh:"离下课还有十分钟。 (Còn 10 phút nữa là tan học.)",zh:"离下课还有十分钟。",pinyin:"Lí xiàkè hái yǒu shí fēnzhōng.",vi:"Còn 10 phút nữa là tan học."}],tables:null,exercises:null},{id:"hsk2_b9_g3",num:3,title:"Bổ ngữ thời lượng (1)",explanation:"Bổ ngữ thời lượng đứng sau động từ để biểu thị khoảng thời gian kéo dài của một hành động (ví dụ: làm trong bao lâu, ngủ mấy tiếng, học mấy năm).",formula:`1. Không có tân ngữ: S + V + (了) + Khoảng thời gian
2. Có tân ngữ: S + V + O + V + (了) + Khoảng thời gian
3. Động từ ly hợp (V+O): S + V + (了) + Khoảng thời gian + O`,note:`1. Với động từ có tân ngữ thường, bắt buộc phải lặp lại động từ: 我看书看了一个小时。
2. Với từ ly hợp (睡觉, 打电话, 散步), chèn khoảng thời gian vào giữa: 睡了八个小时觉, 打了一个小时电话.`,examples:[{rawZh:"他睡了八个小时。 (Anh ấy đã ngủ 8 tiếng đồng hồ.)",zh:"他睡了八个小时。",pinyin:"Tā shuì le bā gè xiǎoshí.",vi:"Anh ấy đã ngủ 8 tiếng đồng hồ."},{rawZh:"我们等了三十分钟。 (Chúng tôi đã đợi 30 phút rồi.)",zh:"我们等了三十分钟。",pinyin:"Wǒmen děng le sānshí fēnzhōng.",vi:"Chúng tôi đã đợi 30 phút rồi."},{rawZh:"我看书看了两个小时。 (Tôi đọc sách được 2 tiếng - Lặp lại động từ 看).",zh:"我看书看了两个小时。",pinyin:"Wǒ kànshū kàn le liǎng gè xiǎoshí.",vi:"Tôi đọc sách được 2 tiếng."},{rawZh:"他学汉语学了三年。 (Anh ấy học tiếng Hán được 3 năm.)",zh:"他学汉语学了三年。",pinyin:"Tā xué Hànyǔ xué le sān nián.",vi:"Anh ấy học tiếng Hán được 3 năm."},{rawZh:"他打了一个小时电话。 (Anh ấy gọi điện thoại được 1 tiếng - Từ ly hợp 打电话).",zh:"他打了一个小时电话。",pinyin:"Tā dǎ le yí gè xiǎoshí diànhuà.",vi:"Anh ấy gọi điện thoại được 1 tiếng."},{rawZh:"我们散了半个小时步。 (Chúng tôi đi dạo được nửa tiếng.)",zh:"我们散了半个小时步。",pinyin:"Wǒmen sàn le bàn gè xiǎoshí bù.",vi:"Chúng tôi đi dạo được nửa tiếng."}],tables:null,exercises:null}]},{lessonId:10,lessonKey:"Bài 10",lessonTitleZh:"就要考试了",lessonTitleFull:"Bài 10: 就要考试了",grammarPoints:[{id:"hsk2_b10_g1",num:1,title:"Câu có cụm Chủ - Vị làm vị ngữ",explanation:"Là câu mà vị ngữ chính là một cụm chủ - vị (bao gồm một chủ ngữ nhỏ S2 và một vị ngữ nhỏ V/Adj2). Cấu trúc này thường dùng để miêu tả đặc điểm, trạng thái hoặc sức khỏe của chủ ngữ lớn S1.",formula:"S1 (Chủ ngữ lớn) + [S2 (Chủ ngữ nhỏ) + V/Adj (Vị ngữ nhỏ)]",note:null,examples:[{rawZh:"他身体很好。 (Anh ấy sức khỏe rất tốt - S1: 他, S2: 身体, Vị ngữ: 很好).",zh:"他身体很好。",pinyin:"Tā shēntǐ hěn hǎo.",vi:"Anh ấy sức khỏe rất tốt."},{rawZh:"今天天气很冷。 (Hôm nay thời tiết rất lạnh.)",zh:"今天天气很冷。",pinyin:"Jīntiān tiānqì hěn lěng.",vi:"Hôm nay thời tiết rất lạnh."},{rawZh:"这个电影我很喜欢。 (Bộ phim này tôi rất thích.)",zh:"这个电影我很喜欢。",pinyin:"Zhè gè diànyǐng wǒ hěn xǐhuan.",vi:"Bộ phim này tôi rất thích."},{rawZh:"这件事情我不清楚。 (Việc này tôi không rõ.)",zh:"这件事情我不清楚。",pinyin:"Zhè jiàn shìqing wǒ bù qīngchu.",vi:"Việc này tôi không rõ."}],tables:null,exercises:null},{id:"hsk2_b10_g2",num:2,title:"Câu hỏi lựa chọn với “还是”",explanation:'Dùng để đưa ra hai (hoặc nhiều) phương án để người nghe lựa chọn một trong số đó ("... hay là...?").',formula:"A + 还是 + B?",note:'LƯU Ý QUAN TRỌNG: Vì bản thân từ "还是" đã mang nghĩa nghi vấn lựa chọn, nên tuyệt đối KHÔNG thêm trợ từ "吗" ở cuối câu.',examples:[{rawZh:"你喝茶还是喝咖啡？ (Bạn uống trà hay uống cà phê?)",zh:"你喝茶还是喝咖啡？",pinyin:"Nǐ hē chá háishì hē kāfēi?",vi:"Bạn uống trà hay uống cà phê?"},{rawZh:"你想坐公交车还是打车？ (Bạn muốn đi xe buýt hay gọi taxi?)",zh:"你想坐公交车还是打车？",pinyin:"Nǐ xiǎng zuò gōngjiāochē háishì dǎchē?",vi:"Bạn muốn đi xe buýt hay gọi taxi?"},{rawZh:"他是老师还是学生？ (Anh ấy là giáo viên hay học sinh?)",zh:"他是老师还是学生？",pinyin:"Tā shì lǎoshī háishì xuésheng?",vi:"Anh ấy là giáo viên hay học sinh?"},{rawZh:"你今天去还是明天去？ (Bạn đi hôm nay hay đi ngày mai?)",zh:"你今天去还是明天去？",pinyin:"Nǐ jīntiān qù háishì míngtiān qù?",vi:"Bạn đi hôm nay hay đi ngày mai?"}],tables:null,exercises:null},{id:"hsk2_b10_g3",num:3,title:"Cấu trúc sắp sửa xảy ra “要 / 快 / 快要 / 就要……了”",explanation:'Dùng để diễn tả một hành động hoặc trạng thái sắp sửa xảy ra trong tương lai gần ("Sắp... rồi").',formula:"S + [要 / 快 / 快要 / 就要] + [Động từ / Tính từ] + 了",note:`MẸO PHÂN BIỆT RẤT QUAN TRỌNG TRONG ĐỀ THI HSK:
1. Có trạng ngữ thời gian cụ thể (như 明天, 下周, 8点, 5分钟以后): BẮT BUỘC dùng 就要……了 (KHÔNG dùng 快 / 快要).
2. Không có thời gian cụ thể (chỉ nhìn hiện tượng đoán sắp xảy ra): Dùng 快 / 快要 / 要……了.`,examples:[{rawZh:"电影要开始了。 (Phim sắp bắt đầu rồi.)",zh:"电影要开始了。",pinyin:"Diànyǐng yào kāishǐ le.",vi:"Phim sắp bắt đầu rồi."},{rawZh:"我妹妹要上大学了。 (Em gái tôi sắp vào đại học rồi.)",zh:"我妹妹要上大学了。",pinyin:"Wǒ mèimei yào shàng dàxué le.",vi:"Em gái tôi sắp vào đại học rồi."},{rawZh:"快下雨了。 (Sắp mưa rồi.)",zh:"快下雨了。",pinyin:"Kuài xià yǔ le.",vi:"Sắp mưa rồi."},{rawZh:"快要考试了。 (Sắp thi rồi.)",zh:"快要考试了。",pinyin:"Kuàiyào kǎoshì le.",vi:"Sắp thi rồi."},{rawZh:"下周就要考试了。 (Tuần sau là đến kỳ thi rồi - Có mốc thời gian 下周 -> Dùng 就要).",zh:"下周就要考试了。",pinyin:"Xià zhōu jiù yào kǎoshì le.",vi:"Tuần sau là đến kỳ thi rồi."},{rawZh:"五分钟以后就要出发了。 (5 phút nữa là xuất phát rồi - Có mốc 5 phút -> Dùng 就要).",zh:"五分钟以后就要出发了。",pinyin:"Wǔ fēnzhōng yǐhòu jiù yào chūfā le.",vi:"5 phút nữa là xuất phát rồi."},{rawZh:"八点就要上课了，快点儿！ (8 giờ là vào lớp rồi, nhanh lên!)",zh:"八点就要上课了，快点儿！",pinyin:"Bā diǎn jiù yào shàngkè le, kuài diǎnr!",vi:"8 giờ là vào lớp rồi, nhanh lên!"}],tables:null,exercises:null}]},{lessonId:11,lessonKey:"Bài 11",lessonTitleZh:"我最喜欢吃中国菜",lessonTitleFull:"Bài 11: 我最喜欢吃中国菜",grammarPoints:[{id:"hsk2_b11_g1",num:1,title:"Trợ từ động thái “着” (Biểu thị sự duy trì của trạng thái)",explanation:"Trợ từ “着” (zhe) đặt ngay sau động từ để biểu thị trạng thái đang tiếp diễn hoặc sự duy trì của tư thế, trạng thái đồ vật/con người.",formula:`Khẳng định: S + V + 着 + (O)
Phủ định: S + 没(有) + V + 着 + (O)
Nghi vấn: S + V + 着 + (O) + 没有 / 吗?`,note:`PHÂN BIỆT "在" VÀ "着":
- 在 + V: Diễn tả HÀNH ĐỘNG đang diễn ra (đang làm gì, ví dụ: 他在穿衣服 - Anh ấy đang mặc áo vào người).
- V + 着: Diễn tả TRẠNG THÁI đang duy trì (đang mang/mặc trên người, ví dụ: 他穿着红色的衣服 - Anh ấy đang mặc chiếc áo màu đỏ).`,examples:[{rawZh:"桌子上放着一本书。 (Trên bàn đang đặt một quyển sách.)",zh:"桌子上放着一本书。",pinyin:"Zhuōzi shàng fàng zhe yì běn shū.",vi:"Trên bàn đang đặt một quyển sách."},{rawZh:"他穿着红色的衣服。 (Anh ấy đang mặc chiếc áo màu đỏ.)",zh:"他穿着红色的衣服。",pinyin:"Tā chuān zhe hóngsè de yīfu.",vi:"Anh ấy đang mặc chiếc áo màu đỏ."},{rawZh:"你穿着鞋吗？ (Bạn đang đi giày à?)",zh:"你穿着鞋吗？",pinyin:"Nǐ chuān zhe xié ma?",vi:"Bạn đang đi giày à?"},{rawZh:"桌子上没放着书。 (Trên bàn không đặt sách.)",zh:"桌子上没放着书。",pinyin:"Zhuōzi shàng méi fàng zhe shū.",vi:"Trên bàn không đặt sách."}],tables:null,exercises:null},{id:"hsk2_b11_g2",num:2,title:"Phó từ chỉ mức độ cao nhất “最” (So sánh bậc nhất)",explanation:'Phó từ “最” (zuì) dùng để biểu thị mức độ cao nhất (so sánh bậc nhất), dịch là "nhất". Thường đứng trước tính từ hoặc các động từ chỉ cảm xúc, tâm lý.',formula:"S + 最 + [Tính từ / Động từ tâm lý: 喜欢, 想, 爱, 希望...]",note:'Vì "最" đã là mức độ cao nhất rồi, nên phía trước không dùng thêm 很, 非常, 真.',examples:[{rawZh:"我最喜欢吃北京烤鸭。 (Tôi thích ăn vịt quay Bắc Kinh nhất.)",zh:"我最喜欢吃北京烤鸭。",pinyin:"Wǒ zuì xǐhuan chī Běijīng kǎoyā.",vi:"Tôi thích ăn vịt quay Bắc Kinh nhất."},{rawZh:"她是班里最漂亮的学⽣。 (Cô ấy là học sinh xinh nhất lớp.)",zh:"她是班里最漂亮的学⽣。",pinyin:"Tā shì bān lǐ zuì piàoliang de xuésheng.",vi:"Cô ấy là học sinh xinh nhất lớp."},{rawZh:"这件衣服最便宜。 (Chiếc áo này là rẻ nhất.)",zh:"这件衣服最便宜。",pinyin:"Zhè jiàn yīfu zuì piányi.",vi:"Chiếc áo này là rẻ nhất."},{rawZh:"我最想去西安旅游。 (Tôi muốn đi Tây An du lịch nhất.)",zh:"我最想去西安旅游。",pinyin:"Wǒ zuì xiǎng qù Xī'ān lǚyóu.",vi:"Tôi muốn đi Tây An du lịch nhất."},{rawZh:"今天天气最好。 (Thời tiết hôm nay là đẹp nhất.)",zh:"今天天气最好。",pinyin:"Jīntiān tiānqì zuì hǎo.",vi:"Thời tiết hôm nay là đẹp nhất."}],tables:null,exercises:null}]},{lessonId:12,lessonKey:"Bài 12",lessonTitleZh:"这里比北京冷多了",lessonTitleFull:"Bài 12: 这里比北京冷多了",grammarPoints:[{id:"hsk2_b12_g1",num:1,title:"Câu so sánh chênh lệch lớn với “多了 / 得多” (3)",explanation:'Trong câu so sánh dùng “比”, đặt “多了” (duō le) hoặc “得多” (de duō) ở sau tính từ để nhấn mạnh sự chênh lệch, khác biệt rất lớn về mức độ giữa hai đối tượng A và B ("... hơn nhiều", "... hơn hẳn").',formula:"A + 比 + B + Tính từ + 多了 / 得多",note:"Tuyệt đối KHÔNG dùng các phó từ 很, 非常 trước tính từ khi đã có 多了 hoặc 得多.",examples:[{rawZh:"今天比昨天热多了。 (Hôm nay nóng hơn hôm qua nhiều.)",zh:"今天比昨天热多了。",pinyin:"Jīntiān bǐ zuótiān rè duō le.",vi:"Hôm nay nóng hơn hôm qua nhiều."},{rawZh:"他比我高得多。 (Anh ấy cao hơn tôi rất nhiều.)",zh:"他比我高得多。",pinyin:"Tā bǐ wǒ gāo de duō.",vi:"Anh ấy cao hơn tôi rất nhiều."},{rawZh:"这件衣服比那件便宜多了。 (Chiếc áo này rẻ hơn chiếc kia nhiều.)",zh:"这件衣服比那件便宜多了。",pinyin:"Zhè jiàn yīfu bǐ nà jiàn piányi duō le.",vi:"Chiếc áo này rẻ hơn chiếc kia nhiều."},{rawZh:"你的汉语比我好得多。 (Tiếng Trung của bạn tốt hơn của tôi rất nhiều.)",zh:"你的汉语比我好得多。",pinyin:"Nǐ de Hànyǔ bǐ wǒ hǎo de duō.",vi:"Tiếng Trung của bạn tốt hơn của tôi rất nhiều."},{rawZh:"这儿的风景比那儿漂亮多了。 (Phong cảnh ở đây đẹp hơn ở đó nhiều.)",zh:"这儿的风景比那儿漂亮多了。",pinyin:"Zhèr de fēngjǐng bǐ nàr piàoliang duō le.",vi:"Phong cảnh ở đây đẹp hơn ở đó nhiều."}],tables:null,exercises:null},{id:"hsk2_b12_g2",num:2,title:"Câu so sánh kết hợp Bổ ngữ trạng thái (4)",explanation:"Dùng để so sánh mức độ thực hiện hành động giữa hai đối tượng A và B (ai làm việc gì nhanh hơn, tốt hơn, đẹp hơn).",formula:`Cách 1: S1 + 比 + S2 + V + 得 + Tính từ
Cách 2: S1 + V + 得 + 比 + S2 + Tính từ
Khi có tân ngữ: S1 + (V) + O + V + 得 + 比 + S2 + Tính từ`,note:'Cả hai cách diễn đạt "S1 比 S2 V得 Adj" và "S1 V得比 S2 Adj" đều hoàn toàn chính xác trong tiếng Trung.',examples:[{rawZh:"他比我跑得快。 (Anh ấy chạy nhanh hơn tôi.)",zh:"他比我跑得快。",pinyin:"Tā bǐ wǒ pǎo de kuài.",vi:"Anh ấy chạy nhanh hơn tôi."},{rawZh:"他跑得比我快。 (Anh ấy chạy nhanh hơn tôi.)",zh:"他跑得比我快。",pinyin:"Tā pǎo de bǐ wǒ kuài.",vi:"Anh ấy chạy nhanh hơn tôi."},{rawZh:"他汉语说得比我好。 (Anh ấy nói tiếng Trung tốt hơn tôi.)",zh:"他汉语说得比我好。",pinyin:"Tā Hànyǔ shuō de bǐ wǒ hǎo.",vi:"Anh ấy nói tiếng Trung tốt hơn tôi."},{rawZh:"他写汉字写得比我漂亮。 (Anh ấy viết chữ Hán đẹp hơn tôi.)",zh:"他写汉字写得比我漂亮。",pinyin:"Tā xiě hànzì xiě de bǐ wǒ piàoliang.",vi:"Anh ấy viết chữ Hán đẹp hơn tôi."},{rawZh:"我说汉语说得比他流利。 (Tôi nói tiếng Trung lưu loát hơn anh ấy.)",zh:"我说汉语说得比他流利。",pinyin:"Wǒ shuō Hànyǔ shuō de bǐ tā liúlì.",vi:"Tôi nói tiếng Trung lưu loát hơn anh ấy."},{rawZh:"他打篮球打得比我好。 (Anh ấy chơi bóng rổ giỏi hơn tôi.)",zh:"他打篮球打得比我好。",pinyin:"Tā dǎ lánqiú dǎ de bǐ wǒ hǎo.",vi:"Anh ấy chơi bóng rổ giỏi hơn tôi."}],tables:null,exercises:null}]},{lessonId:13,lessonKey:"Bài 13",lessonTitleZh:"我们爱上中文课",lessonTitleFull:"Bài 13: 我们爱上中文课",grammarPoints:[{id:"hsk2_b13_g1",num:1,title:"Câu mang hai tân ngữ (Động từ song tân ngữ)",explanation:"Một số động từ có thể mang đồng thời hai tân ngữ: Tân ngữ gián tiếp chỉ người (đứng trước) và Tân ngữ trực tiếp chỉ vật/sự việc (đứng sau).",formula:"S + V (给, 问, 教, 送, 告诉, 卖, 买, 拿) + O1 (Chỉ người) + O2 (Chỉ vật)",note:"Các động từ mang 2 tân ngữ phổ biến nhất: 给 (cho), 问 (hỏi), 教 (dạy), 送 (tặng), 告诉 (bảo/nói cho biết), 卖 (bán cho).",examples:[{rawZh:"请给我一杯茶。 (Cho tôi một cốc trà.)",zh:"请给我一杯茶。",pinyin:"Qǐng gěi wǒ yì bēi chá.",vi:"Cho tôi một cốc trà."},{rawZh:"他教我们汉语。 (Anh ấy dạy chúng tôi tiếng Hán.)",zh:"他教我们汉语。",pinyin:"Tā jiāo wǒmen Hànyǔ.",vi:"Anh ấy dạy chúng tôi tiếng Hán."},{rawZh:"他卖给我一个手机。 (Anh ấy bán cho tôi một chiếc điện thoại.)",zh:"他卖给我一个手机。",pinyin:"Tā mài gěi wǒ yí gè shǒujī.",vi:"Anh ấy bán cho tôi một chiếc điện thoại."},{rawZh:"妈妈买给我一件衣服。 (Mẹ mua cho tôi một chiếc áo.)",zh:"妈妈买给我一件衣服。",pinyin:"Māma mǎi gěi wǒ yí jiàn yīfu.",vi:"Mẹ mua cho tôi một chiếc áo."},{rawZh:"你拿给我那个杯子。 (Bạn lấy cho tôi cái cốc đó.)",zh:"你拿给我那个杯子。",pinyin:"Nǐ ná gěi wǒ nà ge bēizi.",vi:"Bạn lấy cho tôi cái cốc đó."}],tables:null,exercises:null},{id:"hsk2_b13_g2",num:2,title:"Câu so sánh chỉ rõ lượng chênh lệch cụ thể (5)",explanation:"Dùng để so sánh và chỉ rõ số lượng chênh lệch chính xác giữa hai đối tượng A và B (ví dụ: lớn hơn 3 tuổi, rẻ hơn 20 tệ, đắt hơn 100 tệ).",formula:"A + 比 + B + Tính từ + [Cụm từ chỉ số lượng: Số từ + Lượng từ + Danh từ]",note:"Khác với so sánh chung chung (多了), ở đây chúng ta đưa ra con số định lượng cụ thể.",examples:[{rawZh:"他比我大三岁。 (Anh ấy lớn hơn tôi 3 tuổi.)",zh:"他比我大三岁。",pinyin:"Tā bǐ wǒ dà sān suì.",vi:"Anh ấy lớn hơn tôi 3 tuổi."},{rawZh:"这双鞋比那双便宜二十块。 (Đôi giày này rẻ hơn đôi kia 20 tệ.)",zh:"这双鞋比那双便宜二十块。",pinyin:"Zhè shuāng xié bǐ nà shuāng piányi èrshí kuài.",vi:"Đôi giày này rẻ hơn đôi kia 20 tệ."},{rawZh:"这件衣服比那件贵一百块。 (Cái áo này đắt hơn cái kia 100 tệ.)",zh:"这件衣服比那件贵一百块。",pinyin:"Zhè jiàn yīfu bǐ nà jiàn guì yìbǎi kuài.",vi:"Cái áo này đắt hơn cái kia 100 tệ."}],tables:null,exercises:null},{id:"hsk2_b13_g3",num:3,title:"Câu so sánh mức độ chênh lệch nhỏ “一点儿 / 一些” (6)",explanation:'Dùng để biểu thị mức độ chênh lệch rất nhỏ, không đáng kể giữa hai đối tượng A và B ("... hơn một chút / hơn một ít").',formula:"A + 比 + B + Tính từ + 一点儿 / 一些",note:'Cấu trúc này đối lập với "多了 / 得多" (chênh lệch lớn). Trong khẩu ngữ "一点儿" được dùng phổ biến nhất.',examples:[{rawZh:"这件衣服比那件便宜一点儿。 (Chiếc áo này rẻ hơn chiếc kia một chút.)",zh:"这件衣服比那件便宜一点儿。",pinyin:"Zhè jiàn yīfu bǐ nà jiàn piányi yìdiǎnr.",vi:"Chiếc áo này rẻ hơn chiếc kia một chút."},{rawZh:"他比我高一些。 (Anh ấy cao hơn tôi một chút.)",zh:"他比我高一些。",pinyin:"Tā bǐ wǒ gāo yìxiē.",vi:"Anh ấy cao hơn tôi một chút."},{rawZh:"这个苹果比那个大一点儿。 (Quả táo này to hơn quả kia một chút.)",zh:"这个苹果比那个大一点儿。",pinyin:"Zhè gè píngguǒ bǐ nà ge dà yìdiǎnr.",vi:"Quả táo này to hơn quả kia một chút."},{rawZh:"今天的作业比昨天的多一些。 (Bài tập hôm nay nhiều hơn hôm qua một chút.)",zh:"今天的作业比昨天的多一些。",pinyin:"Jīntiān de zuòyè bǐ zuótiān de duō yìxiē.",vi:"Bài tập hôm nay nhiều hơn hôm qua một chút."},{rawZh:"这个汉语词比那个难一点儿。 (Từ tiếng Trung này khó hơn từ kia một chút.)",zh:"这个汉语词比那个难一点儿。",pinyin:"Zhè gè Hànyǔ cí bǐ nà ge nán yìdiǎnr.",vi:"Từ tiếng Trung này khó hơn từ kia một chút."}],tables:null,exercises:null}]},{lessonId:14,lessonKey:"Bài 14",lessonTitleZh:"一个人过年多没意思啊",lessonTitleFull:"Bài 14: 一个人过年多没意思啊",grammarPoints:[{id:"hsk2_b14_g1",num:1,title:"Câu tồn hiện trạng thái với “着” (2)",explanation:"Dùng để miêu tả sự tồn tại của người hoặc vật ở một địa điểm cụ thể, nhấn mạnh vào tư thế, trạng thái đang được duy trì liên tục (đang treo, đang đặt, đang ngồi, đang đứng...).",formula:"[Từ chỉ nơi chốn / Địa điểm] + V + 着 + [Cụm số lượng/Lượng từ] + Danh từ",note:`PHÂN BIỆT CÂU TỒN HIỆN "有" VÀ "着":
- Câu với 有: Chỉ đơn thuần thông báo sự tồn tại (Có vật gì ở đó, ví dụ: 房间里有一个人 - Trong phòng có một người).
- Câu với 着: Miêu tả sinh động trạng thái/tư thế của vật/người đó (ví dụ: 房间里坐着一个人 - Trong phòng đang ngồi một người).`,examples:[{rawZh:"墙上挂着一张画。 (Trên tường đang treo một bức tranh.)",zh:"墙上挂着一张画。",pinyin:"Qiáng shàng guà zhe yì zhāng huà.",vi:"Trên tường đang treo một bức tranh."},{rawZh:"桌子上放着一个杯子。 (Trên bàn đang đặt một cái cốc.)",zh:"桌子上放着一个杯子。",pinyin:"Zhuōzi shàng fàng zhe yí gè bēizi.",vi:"Trên bàn đang đặt một cái cốc."},{rawZh:"门口站着一个人。 (Ở cửa đang đứng một người.)",zh:"门口站着一个人。",pinyin:"Ménkǒu zhàn zhe yí gè rén.",vi:"Ở cửa đang đứng một người."},{rawZh:"椅子上坐着一个孩子。 (Trên ghế đang ngồi một đứa bé.)",zh:"椅子上坐着一个孩子。",pinyin:"Yǐzi shàng zuò zhe yí gè háizi.",vi:"Trên ghế đang ngồi một đứa bé."},{rawZh:"黑板上写着几个字。 (Trên bảng đang viết mấy chữ.)",zh:"黑板上写着几个字。",pinyin:"Hēibǎn shàng xiě zhe jǐ gè zì.",vi:"Trên bảng đang viết mấy chữ."}],tables:null,exercises:null},{id:"hsk2_b14_g2",num:2,title:"Phó từ chỉ mức độ “多” trong câu cảm thán",explanation:'Dùng trong câu cảm thán để biểu thị sự ngạc nhiên, khen ngợi hoặc nhấn mạnh mức độ cao của tính chất ("Thật là...", "... biết bao!", "... quá đi thôi!").',formula:"多 + [Tính từ] + (啊 / 啦 / 呀) !",note:"Cấu trúc này thường kết hợp với trợ từ ngữ khí ở cuối câu (啊, 啦, 呀) để tăng sắc thái biểu cảm.",examples:[{rawZh:"今天天气多好啊！ (Thời tiết hôm nay đẹp quá!)",zh:"今天天气多好啊！",pinyin:"Jīntiān tiānqì duō hǎo a!",vi:"Thời tiết hôm nay đẹp quá!"},{rawZh:"这儿的苹果多便宜啊！ (Táo ở đây rẻ thật đấy!)",zh:"这儿的苹果多便宜啊！",pinyin:"Zhèr de píngguǒ duō piányi a!",vi:"Táo ở đây rẻ thật đấy!"},{rawZh:"你的字写得多漂亮啊！ (Chữ của bạn viết đẹp quá!)",zh:"你的字写得多漂亮啊！",pinyin:"Nǐ de zì xiě de duō piàoliang a!",vi:"Chữ của bạn viết đẹp quá!"},{rawZh:"他多聪明啊！ (Anh ấy thật là thông minh!)",zh:"他多聪明啊！",pinyin:"Tā duō cōngmíng a!",vi:"Anh ấy thật là thông minh!"},{rawZh:"这个孩子多可爱呀！ (Đứa bé này đáng yêu quá!)",zh:"这个孩子多可爱呀！",pinyin:"Zhè gè háizi duō kě'ài ya!",vi:"Đứa bé này đáng yêu quá!"}],tables:null,exercises:null},{id:"hsk2_b14_g3",num:3,title:"Bổ ngữ xu hướng kép (V + 进/出/上/下/回/过/起 + 来/去)",explanation:"Bổ ngữ xu hướng kép được tạo thành bởi: Động từ + [进/出/上/下/回/过/起] + [来/去]. Nó giúp xác định rõ hướng đi chi tiết của hành động di chuyển kết hợp với vị trí mốc của người nói.",formula:`1. Động từ + Xu hướng + 来 / 去
2. Tân ngữ là ĐỊA ĐIỂM (Bắt buộc ở giữa): V + [进/出/上/下/回/过] + Địa điểm + 来/去
3. Tân ngữ là ĐỒ VẬT: V + [进/出/上/下/回/过] + (Tân ngữ) + 来/去 + (Tân ngữ)`,note:`TẠI SAO BỔ NGỮ XU HƯỚNG KÉP LẠI BẮT BUỘC TRONG TIẾNG TRUNG?
1. Định vị không gian: Người nghe luôn cần biết hành động đang hướng về phía mình (来) hay ra xa mình (去).
2. Hoàn thiện nghĩa động từ: Cung cấp đủ bộ 3 thông tin: Cách thức (chạy) + Hướng đích (vào trong) + Phương vị (về phía tôi).
3. Tránh mơ hồ ngữ nghĩa.`,examples:[{rawZh:"他跑进教室来了。 (Anh ấy chạy vào lớp học rồi - Người nói đang ở trong lớp).",zh:"他跑进教室来了。",pinyin:"Tā pǎo jìn jiàoshì lái le.",vi:"Anh ấy chạy vào lớp học rồi."},{rawZh:"快跑进教室去！ (Mau chạy vào lớp học đi! - Người nói đang ở ngoài hành lang).",zh:"快跑进教室去！",pinyin:"Kuài pǎo jìn jiàoshì qù!",vi:"Mau chạy vào lớp học đi!"},{rawZh:"他拿出了一支笔来。 (Anh ấy lấy ra một chiếc bút).",zh:"他拿出了一支笔来。",pinyin:"Tā ná chū le yì zhī bǐ lái.",vi:"Anh ấy lấy ra một chiếc bút."},{rawZh:"他站起来了。 (Anh ấy đứng dậy rồi - Bắt đầu tư thế đứng).",zh:"他站起来了。",pinyin:"Tā zhàn qǐlái le.",vi:"Anh ấy đứng dậy rồi."},{rawZh:"大家都笑起来了。 (Mọi người bắt đầu cười rộ lên - Nhấn mạnh sự bắt đầu của hành động).",zh:"大家都笑起来了。",pinyin:"Dàjiā dōu xiào qǐlái le.",vi:"Mọi người bắt đầu cười rộ lên."}],tables:null,exercises:null}]},{lessonId:15,lessonKey:"Bài 15",lessonTitleZh:"我想再去一次中国",lessonTitleFull:"Bài 15: 我想再去一次中国",grammarPoints:[{id:"hsk2_b15_g1",num:1,title:"Bổ ngữ động lượng “次” (Số lần thực hiện hành động)",explanation:"Bổ ngữ động lượng dùng để biểu thị số lần thực hiện của một hành động. Từ thông dụng nhất là “次” (cì - lần, chuyến).",formula:`1. Không có tân ngữ: S + V + (过/了) + Số từ + 次
2. Tân ngữ là ĐỒ VẬT: S + V + (过/了) + Số từ + 次 + O (Vật)
3. Tân ngữ là ĐẠI TỪ CHỈ NGƯỜI (Bắt buộc sau tân ngữ): S + V + (过/了) + O (Người) + Số từ + 次
4. Tân ngữ là ĐỊA ĐIỂM (Linh hoạt): Đặt trước hoặc sau "Số từ + 次" đều đúng`,note:`Quy tắc vị trí tân ngữ với bổ ngữ động lượng:
- Tân ngữ chỉ người: Bắt buộc đặt TRƯỚC "次" (ví dụ: 我找过他一次).
- Tân ngữ chỉ vật: Thường đặt SAU "次" (ví dụ: 我看过两次电影).
- Tân ngữ chỉ nơi chốn: Đặt trước hay sau "次" đều chuẩn (我去过两次北京 / 我去过北京两次).`,examples:[{rawZh:"我去过两次。 (Tôi đã đi qua hai lần.)",zh:"我去过两次。",pinyin:"Wǒ qù guo liǎng cì.",vi:"Tôi đã đi qua hai lần."},{rawZh:"他看了一次。 (Anh ấy xem một lần.)",zh:"他看了一次。",pinyin:"Tā kàn le yí cì.",vi:"Anh ấy xem một lần."},{rawZh:"我们听了三次。 (Chúng tôi nghe ba lần.)",zh:"我们听了三次。",pinyin:"Wǒmen tīng le sān cì.",vi:"Chúng tôi nghe ba lần."},{rawZh:"我看过两次电影。 (Tôi đã xem phim hai lần - Tân ngữ là vật).",zh:"我看过两次电影。",pinyin:"Wǒ kàn guo liǎng cì diànyǐng.",vi:"Tôi đã xem phim hai lần."},{rawZh:"他读了三次书。 (Anh ấy đọc sách ba lần.)",zh:"他读了三次书。",pinyin:"Tā dú le sān cì shū.",vi:"Anh ấy đọc sách ba lần."},{rawZh:"我找过他一次。 (Tôi đã tìm anh ấy một lần - Tân ngữ chỉ người 他 đứng trước 一次).",zh:"我找过他一次。",pinyin:"Wǒ zhǎo guo tā yí cì.",vi:"Tôi đã tìm anh ấy một lần."},{rawZh:"老师叫过你两次。 (Thầy giáo đã gọi bạn hai lần.)",zh:"老师叫过你两次。",pinyin:"Lǎoshī jiào guo nǐ liǎng cì.",vi:"Thầy giáo đã gọi bạn hai lần."},{rawZh:"我去过北京两次。 / 我去过两次北京。 (Tôi đã đi Bắc Kinh hai lần - Tân ngữ địa điểm).",zh:"我去过北京两次。",pinyin:"Wǒ qù guo Běijīng liǎng cì.",vi:"Tôi đã đi Bắc Kinh hai lần."},{rawZh:"他来过我家三次。 (Anh ấy đã đến nhà tôi ba lần.)",zh:"他来过我家三次。",pinyin:"Tā lái guo wǒ jiā sān cì.",vi:"Anh ấy đã đến nhà tôi ba lần."}],tables:null,exercises:null},{id:"hsk2_b15_g2",num:2,title:"Câu chữ “有” chỉ số lượng đạt đến mức độ (S + 有 + Số lượng + 了)",explanation:'Câu chữ “有” kết hợp với cụm từ chỉ số lượng và trợ từ “了” ở cuối câu dùng để nhấn mạnh rằng một người hoặc sự vật đã đạt đến một mức độ, số lượng, độ tuổi hoặc trọng lượng cụ thể ("Đã được...", "Đã nặng đến...", "Đã có đến...").',formula:"S + 有 + [Cụm từ chỉ số lượng / Lượng từ + Danh từ] + 了",note:"Biểu thị sự phát triển hoặc số lượng đã chạm tới một ngưỡng mốc đáng kể.",examples:[{rawZh:"她妹妹有三岁了。 (Em gái cô ấy đã được 3 tuổi rồi - Đạt đến ngưỡng 3 tuổi).",zh:"她妹妹有三岁了。",pinyin:"Tā mèimei yǒu sān suì le.",vi:"Em gái cô ấy đã được 3 tuổi rồi."},{rawZh:"我现在有五百块了。 (Bây giờ tôi đã có 500 tệ rồi).",zh:"我现在有五百块了。",pinyin:"Wǒ xiànzài yǒu wǔbǎi kuài le.",vi:"Bây giờ tôi đã có 500 tệ rồi."},{rawZh:"他书包里有十本书了。 (Trong cặp sách của anh ấy đã có 10 quyển sách rồi).",zh:"他书包里有十本书了。",pinyin:"Tā shūbāo lǐ yǒu shí běn shū le.",vi:"Trong cặp sách của anh ấy đã có 10 quyển sách rồi."},{rawZh:"这个西瓜有十斤了。 (Quả dưa hấu này đã nặng đến 10 cân rồi).",zh:"这个西瓜有十斤了。",pinyin:"Zhè gè xīguā yǒu shí jīn le.",vi:"Quả dưa hấu này đã nặng đến 10 cân rồi."},{rawZh:"那棵树有两米高了。 (Cái cây kia đã cao đến 2 mét rồi).",zh:"那棵树有两米高了。",pinyin:"Nà kē shù yǒu liǎng mǐ gāo le.",vi:"Cái cây kia đã cao đến 2 mét rồi."}],tables:null,exercises:null}]}];typeof window<"u"&&(window.HSK2_STRUCTURED_GRAMMAR=h);export{n as H,h as a};
